calc.mjs.text:
// Cross-marketplace net-profit arithmetic for one item sold on several
// channels. No network, no state, no stored rate schedule: every fee is an
// input, and the presets below are illustrative starting points a seller is
// expected to replace with the numbers on their own statements. That keeps the
// output a transparent calculation the seller can check rather than a claim
// about any marketplace's current published fees.

/**
 * Illustrative defaults for the channels a small seller most often chooses
 * between. Fee *shapes* differ between them in ways that flat "X% fee"
 * comparisons hide, which is the whole reason this tool exists:
 *
 *   - a per-listing fee is charged whether or not the item sells (Etsy),
 *   - a monthly subscription only makes sense amortised over orders (Amazon
 *     Professional, an own store on Shopify),
 *   - some channels bundle payment processing into the commission (eBay's
 *     final value fee), others bill it separately (Etsy Payments).
 *
 * `paymentRate` and `adRate` apply to the order total (item price + shipping
 * charged). `commissionRate` does too by default (`commissionBase: "order"`),
 * which is how eBay, Etsy and Amazon compute their selling fees. Reverb is
 * the exception: its selling fee applies to the item price only
 * (`commissionBase: "item"`), matching `ventures/reverb-fee-calculator`. A
 * seller whose channel differs can zero one field and fold the rate into
 * another.
 *
 * One channel's schedule is not a rate at all. Poshmark charges a flat $2.95
 * on a sale under $15 and 20% at $15 or more — a cliff, where the *whole*
 * sale is taxed by whichever rule applies rather than a marginal band. A
 * channel can say so with `commissionThreshold` (the price the rule switches
 * at) and `commissionFlatBelow` (the flat fee charged below it), and
 * `calculateChannel` then prices, breaks even and solves for a target on
 * whichever side of the cliff the item actually sits. A channel that omits
 * both fields is unaffected, down to the arithmetic: every coefficient below
 * collapses to what it was before the cliff existed. Grailed's step is a
 * lower percentage below the threshold rather than a flat fee, which a channel
 * says with `commissionRateBelow`.
 */

export const CHANNEL_PRESETS = [
  {
    id: "ebay",
    label: "eBay",
    note: "The final value fee normally covers payment processing, so the separate processor rate is 0 here. Sell-through and days to sell are illustrative starting points, not a claim about how fast eBay actually sells.",
    commissionRate: 13.6,
    paymentRate: 0,
    paymentFixed: 0.4,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions, not a published marketplace rate.
    // eBay buyers usually pay outbound; sellers often eat return postage and
    // get the final-value fee back. Replace with your own return report.
    returnRate: 8,
    returnShippingCost: 6,
    resellableRate: 90,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions. A fixed-price listing renews on a
    // 30-day cycle, which costs nothing while the per-listing fee is zero but
    // matters the moment a seller enters an insertion fee above their free
    // allowance.
    sellThroughPct: 65,
    daysToSell: 21,
    listingRenewalDays: 30,
  },
  {
    id: "etsy",
    label: "Etsy",
    note: "Listing fee is charged per listing whether or not it sells; transaction fee and Etsy Payments are billed separately. Sell-through and days to sell are illustrative starting points, not a claim about Etsy sell-through.",
    commissionRate: 6.5,
    paymentRate: 3,
    paymentFixed: 0.25,
    perListingFee: 0.2,
    monthlyFee: 0,
    adRate: 0,
    returnRate: 4,
    returnShippingCost: 6,
    resellableRate: 85,
    feeRefundRate: 100,
    // An Etsy listing expires after four months and is charged again when it
    // renews, so a slow-selling item pays the listing fee more than once.
    sellThroughPct: 35,
    daysToSell: 45,
    listingRenewalDays: 120,
  },
  {
    id: "amazon",
    label: "Amazon (Professional)",
    note: "Referral fee plus the monthly Professional plan. Put FBA or pick-and-pack under fulfilment cost, not here. Sell-through and days to sell are illustrative starting points, not a claim about Amazon velocity.",
    commissionRate: 15,
    paymentRate: 0,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 39.99,
    adRate: 0,
    // Amazon return rates run higher than most channels, especially apparel.
    returnRate: 18,
    returnShippingCost: 7,
    resellableRate: 80,
    feeRefundRate: 100,
    sellThroughPct: 55,
    daysToSell: 28,
    listingRenewalDays: 0,
  },
  {
    id: "mercari",
    label: "Mercari",
    note: "Mercari's current schedule (listings created or updated on or after January 6, 2025) charges a single 10% selling fee on the item price plus any buyer-paid shipping, with no separate payment processing fee -- a still-unedited older listing may instead be on the pre-2025 schedule, which `ventures/mercari-fee-calculator`'s own schedule comparison covers and this page does not model. Sell-through and days to sell are illustrative starting points, not a claim about Mercari velocity.",
    // Matches ventures/mercari-fee-calculator's own SELLING_FEE_RATE (10%,
    // current schedule, as of September 2026). Two tools in one portfolio
    // printing different fee assumptions for the same marketplace is a
    // credibility problem, so `channel-parity.test.mjs` asserts these stay
    // equal by importing that calculator's own constant rather than
    // restating it, the same rule the Reverb, TikTok Shop, Whatnot, Poshmark
    // and StockX rows below follow.
    commissionRate: 10,
    paymentRate: 0,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions. Mercari skews toward lower-priced,
    // casual and used goods, so this starts a little above eBay's.
    returnRate: 10,
    returnShippingCost: 6,
    resellableRate: 88,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: a lower average price point tends
    // to move faster than a general marketplace listing of the same kind.
    sellThroughPct: 55,
    daysToSell: 18,
    listingRenewalDays: 0,
  },
  {
    id: "reverb",
    label: "Reverb (musical gear)",
    note: "Off by default because it only applies to instruments and audio gear — turn it on if that is what you sell. Reverb bills the selling fee on the item price only (not on shipping charged) and payment processing separately, which is why the processor rate is not zero here the way it is for eBay. Sell-through and days to sell are illustrative starting points, not a claim about Reverb velocity.",
    // Matches ventures/reverb-fee-calculator's own defaults (5% selling fee
    // on the item price, 3.19% + $0.49 Reverb Payments on the order total, as
    // of September 2026). Two tools in one portfolio printing different fee
    // assumptions for the same marketplace is a credibility problem, so
    // `channel-parity.test.mjs` asserts these stay equal by importing that
    // calculator's defaults rather than restating them — including that the
    // selling fee is charged on the item, not on shipping.
    commissionRate: 5,
    commissionBase: "item",
    paymentRate: 3.19,
    paymentFixed: 0.49,
    perListingFee: 0,
    monthlyFee: 0,
    // Bumps are optional and priced per listing rather than as a rate, so they
    // are left at zero here; the dedicated calculator is where that decision
    // gets made (it has a whole page on whether a bump pays for itself).
    adRate: 0,
    // Illustrative return assumptions. Gear buyers inspect on arrival and
    // Reverb's protection means a rejected item usually comes back; the fee is
    // normally refunded with it.
    returnRate: 6,
    returnShippingCost: 18,
    resellableRate: 90,
    feeRefundRate: 100,
    // A Reverb listing does not expire on a cycle, so there is no renewal to
    // charge — but gear is a considered purchase and sits longer than a
    // general-marketplace item of the same price.
    sellThroughPct: 50,
    daysToSell: 35,
    listingRenewalDays: 0,
    // Off until the seller says this is gear: enabled by default it would add
    // a channel most sellers cannot list on to every comparison, and a channel
    // that does not apply is noise in a ranking, not information.
    enabled: false,
  },
  {
    id: "own-store",
    label: "Own store (Shopify Basic)",
    note: "No marketplace commission — you pay the plan and card processing, and you supply the traffic. Sell-through starts low here for the same reason: you bring the buyers.",
    commissionRate: 0,
    paymentRate: 2.9,
    paymentFixed: 0.3,
    perListingFee: 0,
    monthlyFee: 39,
    adRate: 0,
    // Card processors often keep the processing fee on a refunded order.
    returnRate: 10,
    returnShippingCost: 6,
    resellableRate: 90,
    feeRefundRate: 0,
    // No marketplace demand behind the listing: the same item sits longer and
    // more often does not sell at all. This is the cost the fee comparison
    // never shows, and it is why an own store can win on fees and lose on cash.
    sellThroughPct: 20,
    daysToSell: 40,
    listingRenewalDays: 0,
  },
  {
    id: "local",
    label: "Local / direct",
    note: "No platform fee and usually no shipping — the cost is your time and a smaller audience. Sell-through is illustrative: the audience is whoever you can reach yourself.",
    commissionRate: 0,
    paymentRate: 0,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // A hand-to-hand sale has no postage on either side, so it starts with
    // shipping zeroed rather than inheriting the shared shipping numbers.
    shippingCharged: 0,
    shippingCost: 0,
    returnRate: 2,
    returnShippingCost: 0,
    resellableRate: 95,
    feeRefundRate: 100,
    sellThroughPct: 45,
    daysToSell: 14,
    listingRenewalDays: 0,
  },
  {
    id: "tiktok",
    label: "TikTok Shop",
    note: "Off by default because it only applies to sellers running TikTok Shop. Referral fee applies to the order total (matching `ventures/tiktok-shop-fee-calculator`'s U.S. standard rate as of September 2026), and processing is already bundled into it, which is why the separate processor rate is 0 here — the same shape as eBay. Creator affiliate commission and facilitation fees are not modelled on this page; the dedicated calculator is where that decision gets made. Sell-through and days to sell are illustrative starting points, not a claim about TikTok Shop velocity.",
    // Matches ventures/tiktok-shop-fee-calculator's own `FEE_SCHEDULE_PRESETS.us_standard`
    // (6% referral, processing bundled in, as of September 2026). Two tools in
    // one portfolio printing different fee assumptions for the same channel is
    // a credibility problem, so `channel-parity.test.mjs` asserts these stay
    // equal by importing that calculator's own presets rather than restating
    // them.
    commissionRate: 6,
    paymentRate: 0,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions. Live and short-video commerce skews
    // toward impulse buys, so this starts a little above eBay's.
    returnRate: 12,
    returnShippingCost: 6,
    resellableRate: 85,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: a live show or a viral video can
    // sell an item in days, far faster than a static listing, and there is no
    // renewal cycle to charge while it waits.
    sellThroughPct: 55,
    daysToSell: 10,
    listingRenewalDays: 0,
    // Off until the seller says they sell there: enabled by default it would
    // add a channel most sellers cannot list on to every comparison, and a
    // channel that does not apply is noise in a ranking, not information.
    enabled: false,
  },
  {
    id: "whatnot",
    label: "Whatnot (live auction)",
    note: "Off by default because it only applies to sellers running live shows. Commission is on the hammer price only, not shipping (matching `ventures/whatnot-seller-payout`'s standard, uncapped category as of September 2026); processing is billed separately on the full checkout total, the same split as Reverb. The $1,500 commission cap on some categories (TCG, coins, pallets) is not modelled on this page — the dedicated calculator is where that decision gets made. Sell-through and days to sell are illustrative starting points, not a claim about Whatnot velocity.",
    // Matches ventures/whatnot-seller-payout's own `CATEGORY_PRESETS.standard`
    // commission rate and `DEFAULT_PAYMENT_RATE` / `DEFAULT_PAYMENT_FIXED`, as
    // of September 2026. `channel-parity.test.mjs` imports those constants
    // directly rather than restating them, for the same reason as the Reverb
    // and TikTok Shop rows above.
    commissionRate: 8,
    commissionBase: "item",
    paymentRate: 2.9,
    paymentFixed: 0.3,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions. A live auction is watched in real time
    // and often shipped fast, so this starts a little below eBay's.
    returnRate: 5,
    returnShippingCost: 6,
    resellableRate: 90,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: a lot sells (or does not) inside
    // one show, not over weeks, and there is no renewal cycle to charge.
    sellThroughPct: 45,
    daysToSell: 3,
    listingRenewalDays: 0,
    // Off until the seller says they run live shows there: enabled by default
    // it would add a channel most sellers cannot list on to every comparison.
    enabled: false,
  },
  {
    id: "poshmark",
    label: "Poshmark (fashion resale)",
    note: "Off by default because it only applies to clothing, shoes and accessories. Poshmark's fee is a cliff, not a rate: a flat $2.95 on a sale under $15 and 20% at $15 or more, charged on the item price only — the buyer pays a prepaid label that never reaches your payout, so shipping charged and shipping you pay both start at zero here. Below $14.75 the flat fee costs more than 20% would (a $10 sale pays an effective 29.5%), which is the arithmetic a per-item comparison can show and a headline-rate table cannot. Sell-through and days to sell are illustrative starting points, not a claim about Poshmark velocity.",
    // Matches ventures/poshmark-fee-calculator's own PERCENT_RATE, FLAT_FEE
    // and COMMISSION_THRESHOLD as of September 2026. `channel-parity.test.mjs`
    // imports those constants directly rather than restating them, for the
    // same reason as the Reverb, TikTok Shop and Whatnot rows above.
    commissionRate: 20,
    commissionBase: "item",
    commissionThreshold: 15,
    commissionFlatBelow: 2.95,
    // Poshmark's commission covers payment processing; there is no separate
    // processor line and no per-listing or monthly charge.
    paymentRate: 0,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // The buyer buys the prepaid USPS label from Poshmark at checkout. It is
    // not seller revenue and not a seller cost, so both sides start at zero
    // rather than inheriting the shared figures — override them on this
    // channel if you cover a label upgrade yourself.
    shippingCharged: 0,
    shippingCost: 0,
    // Illustrative return assumptions. Poshmark has no buyer's-remorse
    // return: a buyer must open a not-as-described case and Poshmark rules on
    // it, so returns are rarer than on eBay and the return label is Poshmark's
    // rather than the seller's.
    returnRate: 2,
    returnShippingCost: 0,
    resellableRate: 90,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: a closet listing does not expire
    // and is never charged again, but fashion resale sits longer than a
    // general-marketplace item of the same price.
    sellThroughPct: 30,
    daysToSell: 60,
    listingRenewalDays: 0,
    // Off until the seller says this is apparel: enabled by default it would
    // add a channel most sellers cannot list on to every comparison, the same
    // reason Reverb and Whatnot start off.
    enabled: false,
  },
  {
    id: "stockx",
    label: "StockX (sneakers & streetwear)",
    note: "Off by default because it only applies to sneakers, streetwear and graded cards. StockX is a bid/ask marketplace, not a storefront: the buyer pays StockX for delivery, so no postage the buyer pays ever reaches you and shipping charged is pinned to zero here — what you do pay is the label to a verification centre, which is the shared \"shipping you pay\" figure. The seller fee falls as your Seller Level rises and Fast Shipping takes more off it again, so replace the rate with the one on your own dashboard. Sell-through and days to sell are illustrative starting points, not a claim about StockX velocity.",
    // Matches ventures/stockx-seller-payout-calculator's own DEFAULTS (9%
    // seller fee before any Fast Shipping discount, 3% payment processing, no
    // fixed per-order charge, as of September 2026). `channel-parity.test.mjs`
    // imports those defaults directly rather than restating them, for the same
    // reason as the Reverb, TikTok Shop, Whatnot and Poshmark rows above.
    commissionRate: 9,
    // The seller fee is charged on the sale price. With shipping charged
    // pinned to zero below, "item" and "order" would agree today — it is
    // stated anyway so that a seller who overrides shipping charged on this
    // row (a private sale arranged off-platform, say) does not silently start
    // paying StockX's fee on postage StockX never billed.
    commissionBase: "item",
    paymentRate: 3,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // The buyer pays StockX for delivery at checkout; none of it is seller
    // revenue, so this starts at zero rather than inheriting the shared
    // figure — the same rule the Poshmark row above follows, for the same
    // reason. What the seller pays to get the item to a verification centre
    // IS a seller cost, so `shippingCost` is inherited rather than zeroed.
    shippingCharged: 0,
    // Illustrative return assumptions, and a different event from every other
    // channel here: StockX has no buyer's-remorse return, so what comes back
    // is an item that failed verification. The seller pays return postage on
    // it and the fee is not charged on a sale that did not complete, but the
    // pair itself is usually fine to relist.
    returnRate: 3,
    returnShippingCost: 15,
    resellableRate: 95,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: an ask does not expire and is never
    // charged again, but an unpopular size or colourway can sit at a price
    // nobody bids.
    sellThroughPct: 40,
    daysToSell: 30,
    listingRenewalDays: 0,
    // Off until the seller says this is sneakers or streetwear: enabled by
    // default it would add a channel most sellers cannot list on to every
    // comparison, the same reason Reverb, Whatnot and Poshmark start off.
    enabled: false,
  },
  {
    id: "depop",
    label: "Depop (fashion & vintage, US)",
    note: "Off by default because it mostly suits fashion, vintage and streetwear. For a US seller Depop's selling fee is 0%; what comes off is Depop Payments processing at 3.3% of the item plus buyer-paid shipping and $0.45 per sale -- the old \"Depop takes 10%\" figure is still quoted everywhere but no longer applies in the US or UK. UK sellers pay 2.9% + £0.30 and sellers elsewhere a flat 10%, so replace the rates if that is you; `ventures/depop-fee-calculator` covers all three regions and Boosted Listings (an extra 12% on boosted sales), which this page does not. The buyer's own Marketplace fee is added on top of what they pay and never comes out of your payout. Sell-through and days to sell are illustrative starting points, not a claim about Depop velocity.",
    // Matches ventures/depop-fee-calculator's US REGIONS row (0% selling,
    // 3.3% + $0.45 processing, as of October 2026). `channel-parity.test.mjs`
    // imports that table rather than restating it, like the other rows.
    commissionRate: 0,
    paymentRate: 3.3,
    paymentFixed: 0.45,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions: Depop has no buyer's-remorse return
    // window, so returns are rare and happen as not-as-described disputes.
    returnRate: 3,
    returnShippingCost: 6,
    resellableRate: 90,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: listings do not expire or renew,
    // but one-off fashion pieces sit longer than a general-marketplace item.
    sellThroughPct: 35,
    daysToSell: 45,
    listingRenewalDays: 0,
    // Off until the seller says this is fashion: enabled by default it would
    // add a channel most sellers cannot list on, like Poshmark and StockX.
    enabled: false,
  },
  {
    id: "facebook-marketplace",
    label: "Facebook Marketplace (shipped)",
    note: "Off by default because shipped checkout is not available for every item or seller. Prices a shipped Facebook Marketplace order: a 10% selling fee on the item price plus buyer-paid shipping. A local-pickup sale costs nothing, so for a locally sold item the direct-sale row is the better comparison. Facebook also applies an $0.80 minimum fee per shipped sale, which this page does not model (it only matters under $8) -- `ventures/facebook-marketplace-fee-calculator` does, along with the $20 dispute penalty. Sell-through and days to sell are illustrative starting points, not a claim about Marketplace velocity.",
    // Matches ventures/facebook-marketplace-fee-calculator's FEE_RATE (10%,
    // shipped checkout, as of October 2026); parity-tested by import.
    commissionRate: 10,
    paymentRate: 0,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions: casual, mostly used goods.
    returnRate: 6,
    returnShippingCost: 6,
    resellableRate: 88,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: listings do not expire and cost
    // nothing to keep up, and a large local audience moves cheap goods fast.
    sellThroughPct: 50,
    daysToSell: 20,
    listingRenewalDays: 0,
    // Off by default: shipped checkout is not available for every item or
    // seller, and it would otherwise add a ninth row to every comparison.
    enabled: false,
  },
  {
    id: "walmart",
    label: "Walmart Marketplace (seller-fulfilled)",
    note: "Off by default because Walmart Marketplace is invitation-based and only applies to sellers approved there. Prices a seller-fulfilled order: the referral fee is a percentage of the item price (the 'Everything else' 15% starting point from `ventures/walmart-marketplace-calculator`; electronics and grocery are 8%, jewelry 20%, so edit the rate for your category), with no separate payment processing and no monthly plan. Walmart prices shipping into the item price, so buyer-paid shipping starts at zero here. The $0.30 minimum referral fee is not modelled (it only matters under $2), and neither is Walmart Fulfillment Services -- `ventures/walmart-marketplace-calculator` compares WFS against shipping it yourself, which is the follow-up question once Walmart wins here. Sell-through and days to sell are illustrative starting points, not a claim about Walmart velocity.",
    // Matches ventures/walmart-marketplace-calculator's 'Everything else'
    // referral rate, which is also its default; parity-tested by import.
    commissionRate: 15,
    commissionBase: "item",
    paymentRate: 0,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Walmart shows one price with shipping included, so nothing is charged
    // to the buyer on top. The shipping cost the seller pays stays shared.
    shippingCharged: 0,
    // Illustrative return assumptions: a general-merchandise mix, between
    // eBay's and Amazon's.
    returnRate: 10,
    returnShippingCost: 7,
    resellableRate: 85,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: listings do not expire, and a new
    // seller starts without the review history that drives Walmart.com sales.
    sellThroughPct: 40,
    daysToSell: 30,
    listingRenewalDays: 0,
    // Off by default: approval is required, and it would otherwise add a row
    // most sellers cannot act on to every comparison.
    enabled: false,
  },
  {
    id: "tcgplayer",
    label: "TCGplayer (trading cards, US)",
    note: "Off by default because it only suits Magic, Pokemon, Yu-Gi-Oh! and other trading-card singles and sealed product. Prices one single-product order at the Marketplace Level 1-4 schedule: a 10.75% commission on the cards plus the shipping the buyer pays, and a 2.5% + $0.30 transaction fee on the order total. The $0.30 is per order, not per card, so a one-card sale feels it far more than a twenty-card cart; `ventures/tcgplayer-fee-calculator` takes the order size, the Pro seller schedule and the $75-per-product commission cap, none of which this page models (the cap only bites above roughly $700). TCGplayer Direct is not modelled either. The fee table was taken from a search, not the help centre, so check one real payout before repricing a binder. Sell-through and days to sell are illustrative starting points, not a claim about TCGplayer velocity.",
    // Matches ventures/tcgplayer-fee-calculator's standard schedule for a
    // one-card order (10.75% commission, 2.5% + $0.30 transaction fee);
    // parity-tested by import.
    commissionRate: 10.75,
    commissionBase: "order",
    paymentRate: 2.5,
    paymentFixed: 0.3,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions: card orders rarely come back, and
    // mostly as condition disputes on higher-value singles.
    returnRate: 3,
    returnShippingCost: 4,
    resellableRate: 90,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: listings do not expire, and a
    // fully priced single in demand moves quickly while a bulk common does not.
    sellThroughPct: 45,
    daysToSell: 21,
    listingRenewalDays: 0,
    // Off by default: it only suits trading cards.
    enabled: false,
  },
  {
    id: "grailed",
    label: "Grailed (menswear & streetwear, US)",
    note: "Off by default because it only suits menswear, designer and streetwear. Since 20 May 2026 Grailed's commission is a step: 6% on a sale under $120 and 9% on a sale of $120 or more, applied to the whole sale, plus 3.49% + $0.49 payment processing -- so a $120 item can pay you less than a $119.99 one. Grailed's $1.99 minimum commission (it only matters under about $33) is not modelled here; `ventures/grailed-fee-calculator` does, along with international buyers and the $120 cliff. These rates come from third-party fee guides, not Grailed's own help centre, so check one real payout. Sell-through and days to sell are illustrative starting points, not a claim about Grailed velocity.",
    // Matches ventures/grailed-fee-calculator's TIER_THRESHOLD, LOW_RATE,
    // HIGH_RATE and domestic processing; parity-tested by import above $33.
    commissionRate: 9,
    commissionBase: "order",
    commissionThreshold: 120,
    commissionRateBelow: 6,
    paymentRate: 3.49,
    paymentFixed: 0.49,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions: Grailed has no buyer's-remorse return
    // window; returns are not-as-described disputes, so they are rare.
    returnRate: 3,
    returnShippingCost: 8,
    resellableRate: 90,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: listings do not expire, but
    // designer menswear is a narrow audience and sits.
    sellThroughPct: 30,
    daysToSell: 50,
    listingRenewalDays: 0,
    // Off until the seller says this is menswear: enabled by default it would
    // add a channel most sellers cannot list on, like Poshmark and Depop.
    enabled: false,
  },
  {
    id: "discogs",
    label: "Discogs (records, CDs & music media)",
    note: "Off by default because it only suits vinyl, CDs, tapes and other music media. Prices Discogs' published 9% selling fee on the item price plus buyer-paid shipping (the $0.10 minimum and $150 maximum per order are not modelled; the cap only bites above about $1,667) and 2.9% + $0.30 payment processing on the same total. The selling fee is from Discogs' own fee page; Discogs does not publish one processing rate for everyone and third-party figures disagree (2.7% + $0.25 to 3.49% + $0.49), so check one real payout before repricing a crate. Discogs's listing grading, shipping-rate rules and per-country payout differences are not modelled. Sell-through and days to sell are illustrative starting points, not a claim about Discogs velocity.",
    commissionRate: 9,
    commissionBase: "order",
    paymentRate: 2.9,
    paymentFixed: 0.3,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    // Illustrative return assumptions: media is described by grade, so returns
    // are mostly condition disputes.
    returnRate: 4,
    returnShippingCost: 6,
    resellableRate: 80,
    feeRefundRate: 100,
    // Illustrative shelf-time assumptions: listings do not expire, and a
    // common record can sit while a sought-after pressing sells quickly.
    sellThroughPct: 35,
    daysToSell: 45,
    listingRenewalDays: 0,
    // Off until the seller says this is music media: enabled by default it
    // would add a channel most sellers cannot list on.
    enabled: false,
  },
  {
    id: "other",
    label: "Other channel",
    note: "Blank and switched off by default. Turn it on and enter the rates of any channel not listed — GOAT, a craft fair, a wholesale account. Mercari, Poshmark, StockX, Depop, Grailed, Discogs, Facebook Marketplace and Walmart have their own rows above.",
    commissionRate: 0,
    paymentRate: 0,
    paymentFixed: 0,
    perListingFee: 0,
    monthlyFee: 0,
    adRate: 0,
    returnRate: 0,
    returnShippingCost: 0,
    resellableRate: 100,
    feeRefundRate: 100,
    sellThroughPct: 50,
    daysToSell: 30,
    listingRenewalDays: 0,
    // Off until the seller fills it in: a channel with every rate at zero
    // would otherwise win every comparison by default and say nothing.
    enabled: false,
  },
];

function number(value, name, fallback = 0) {
  const raw = value === undefined || value === null || value === "" ? fallback : value;
  const result = Number(raw);
  if (!Number.isFinite(result) || result < 0) throw new Error(`${name} must be a non-negative number`);
  return result;
}

function wholeNumber(value, name, fallback = 0) {
  const result = number(value, name, fallback);
  if (!Number.isInteger(result)) throw new Error(`${name} must be a whole number`);
  return result;
}

function ratePercent(value, name, fallback = 0) {
  const result = number(value, name, fallback);
  if (result > 100) throw new Error(`${name} must be between 0 and 100`);
  return result;
}

// Days-to-sell is optional for cash-per-day. Empty or zero means "I do not
// know yet" and profit-per-day stays null rather than inventing a pace. A
// negative value is a real mistake and is refused. Shelf-time still reads
// the same field as a number (zero when unset) so a missing pace does not
// invent sell-through either.
function optionalPositive(value, name) {
  if (value === undefined || value === null || value === "") return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) {
    throw new Error(`${name} must be a non-negative number`);
  }
  return result === 0 ? null : result;
}

/**
 * Net result for one channel, given the shared item facts.
 *
 * `shared` carries what does not change with the channel (what the item cost
 * you, packaging, other per-unit cash) plus the fallbacks for the per-channel
 * fields, so a seller can enter a price once and still override it for the
 * one channel where they list higher.
 */
export function calculateChannel(channel, shared = {}) {
  if (!channel || typeof channel !== "object") throw new Error("A channel is required");
  const label = channel.label ?? channel.id ?? "Channel";

  const price = number(channel.price, `${label} price`, shared.price);
  const shippingCharged = number(channel.shippingCharged, `${label} shipping charged`, shared.shippingCharged ?? 0);
  const shippingCost = number(channel.shippingCost, `${label} shipping you pay`, shared.shippingCost ?? 0);
  const fulfilmentCost = number(channel.fulfilmentCost, `${label} fulfilment cost`, 0);

  const commissionRate = number(channel.commissionRate, `${label} commission rate`, 0);
  // A fee cliff, for a channel whose commission is not a rate below some
  // price. Zero threshold means "no cliff", which is every channel but
  // Poshmark, and leaves every coefficient below exactly as it was.
  const commissionThreshold = number(channel.commissionThreshold, `${label} commission threshold`, 0);
  const commissionFlatBelow = number(channel.commissionFlatBelow, `${label} flat commission`, 0);
  // Grailed's rule below its $120 step is a lower *percentage*, not a flat fee.
  // When set it replaces the flat fee on that side; unset leaves Poshmark's.
  const commissionRateBelow = number(channel.commissionRateBelow, `${label} commission rate below the threshold`, 0);
  const paymentRate = number(channel.paymentRate, `${label} payment rate`, 0);
  const adRate = number(channel.adRate, `${label} ads rate`, 0);
  const paymentFixed = number(channel.paymentFixed, `${label} payment fixed fee`, 0);
  const perListingFee = number(channel.perListingFee, `${label} listing fee`, 0);
  const monthlyFee = number(channel.monthlyFee, `${label} monthly fee`, 0);

  const itemCost = number(shared.itemCost, "What you paid for the item", 0);
  const packagingCost = number(shared.packagingCost, "Packaging cost", 0);
  const otherCost = number(shared.otherCost, "Other per-item cost", 0);
  const monthlyOrders = wholeNumber(shared.monthlyOrders, "Orders per month", 0);
  const includeSubscription = shared.includeSubscription !== false;
  const daysToSellInput = channel.daysToSell !== undefined && channel.daysToSell !== ""
    ? channel.daysToSell
    : shared.daysToSell;
  const daysToSell = optionalPositive(daysToSellInput, `${label} days to sell`);

  // Expected sales on THIS channel. Empty falls back to the shared monthly
  // figure, so existing comparisons stay unchanged. When a seller overrides
  // it, that number is also what a monthly plan is spread over — otherwise a
  // $39 Shopify plan amortized over 100 "portfolio" orders then multiplied by
  // 20 own-store sales would understate the plan by 5×.
  const rawChannelVolume = channel.expectedMonthlySales;
  const hasChannelVolume = rawChannelVolume !== undefined && rawChannelVolume !== null && rawChannelVolume !== "";
  const expectedMonthlySales = hasChannelVolume
    ? wholeNumber(rawChannelVolume, `${label} expected monthly sales`)
    : monthlyOrders;

  // A subscription is only a per-order cost once it is spread over the orders
  // it carries. Comparing a $39/month store against a per-sale marketplace
  // without that share is the mistake this line exists to prevent — and with
  // no order volume to spread it over the question has no answer, so say so
  // instead of quietly dividing by zero.
  let subscriptionShare = 0;
  let unamortizedMonthlyFee = 0;
  if (includeSubscription && monthlyFee > 0) {
    if (expectedMonthlySales < 1) {
      if (hasChannelVolume) {
        // Explicit zero volume on this channel: there is no per-sale share,
        // but the plan is still paid that month.
        unamortizedMonthlyFee = monthlyFee;
      } else {
        throw new Error("Enter how many orders a month you expect, so monthly fees can be spread over them");
      }
    } else {
      subscriptionShare = monthlyFee / expectedMonthlySales;
    }
  }

  const revenue = price + shippingCharged;
  // Most marketplaces take the selling fee on the order total. Reverb takes
  // it on the item price only; payment processing still runs on the order.
  // Splitting the two bases is what keeps this page's Reverb row equal to
  // `reverb-fee-calculator` when shipping charged is non-zero.
  const commissionBase = channel.commissionBase === "item" ? "item" : "order";

  // Below a fee cliff the percentage is not charged at all — a flat fee stands
  // in its place — so the rate leaves the coefficients entirely and the flat
  // fee joins the fixed cash instead. Every price-solving closed form below is
  // therefore written against *one side* of the cliff, and the two solvers pick
  // the side whose answer actually lands in its own price range.
  const hasFeeCliff = commissionThreshold > 0;
  const commissionBaseAt = (itemPrice) =>
    commissionBase === "item" ? itemPrice : itemPrice + shippingCharged;
  // `chargesRate` false is the flat-fee side of the cliff.
  const branchRates = (chargesRate) => {
    const rate = chargesRate ? commissionRate : commissionRateBelow;
    return {
      orderRate: (paymentRate + adRate + (commissionBase === "order" ? rate : 0)) / 100,
      itemRate: (commissionBase === "item" ? rate : 0) / 100,
    };
  };
  const flatCommissionOn = (chargesRate) => (chargesRate || commissionRateBelow > 0 ? 0 : commissionFlatBelow);

  const commissionBaseAmount = commissionBaseAt(price);
  // Which side this item is actually on. Poshmark's switch is at exactly
  // $15.00 and the higher rule owns the boundary: a $15.00 sale pays 20%, not
  // the flat fee.
  const chargesRate = !(hasFeeCliff && commissionBaseAmount < commissionThreshold);
  const { orderRate, itemRate } = branchRates(chargesRate);
  const percentRate = orderRate + itemRate;
  if (percentRate >= 1) {
    throw new Error(`${label}: commission, payment and ad rates add up to 100% or more of the order`);
  }

  const fees = {
    commission: chargesRate
      ? (commissionBaseAmount * commissionRate) / 100
      // A flat fee cannot take more than the sale it is charged on, which is
      // how `poshmark-fee-calculator`'s own `commissionFor` caps it. Only
      // reachable below the flat fee itself, and never inside a break-even
      // answer: the solved flat-branch price is at least the flat fee
      // whenever there is any cash to recover.
      : commissionRateBelow > 0
        ? (commissionBaseAmount * commissionRateBelow) / 100
        : Math.min(commissionFlatBelow, commissionBaseAmount),
    payment: (revenue * paymentRate) / 100 + paymentFixed,
    ads: (revenue * adRate) / 100,
    listing: perListingFee,
    subscription: subscriptionShare,
  };
  const feeTotal = Object.values(fees).reduce((sum, value) => sum + value, 0);

  // Cash you lay out to source, pack and ship. Fees come out of the sale
  // proceeds rather than your pocket, so they stay out of invested cash and
  // return-on-investment stays honest.
  const cashInvested = itemCost + packagingCost + otherCost + shippingCost + fulfilmentCost;
  const profit = revenue - feeTotal - cashInvested;

  // Cash that must be recovered before any percentage fee is covered. Used for
  // both break-even and the price that reaches a given profit. Below a fee
  // cliff the flat commission is exactly that kind of cash, so it belongs
  // here — and is zero on the percentage side and for every channel with no
  // cliff at all.
  const fixedCashOn = (chargesRateOnBranch) =>
    paymentFixed + perListingFee + subscriptionShare + cashInvested
    + flatCommissionOn(chargesRateOnBranch);
  const fixedCash = fixedCashOn(chargesRate);

  // profit = price*(1 - orderRate - itemRate) + shippingCharged*(1 - orderRate) - fixedCash
  // Collapses to the familiar fixedCash/(1 - percentRate) - shippingCharged
  // whenever commission also runs on the order (itemRate === 0). The
  // coefficient is taken per branch below rather than once here, because a
  // cliff channel has a different one on each side.

  /**
   * Item price at which the *sold-sale* keep equals `target`, solved on one
   * side of a fee cliff. Null when the rates leave no reachable price.
   */
  const soldPriceOnBranch = (target, chargesRateOnBranch) => {
    const { orderRate: order, itemRate: item } = branchRates(chargesRateOnBranch);
    const coeff = 1 - order - item;
    if (coeff <= 0) return null;
    const solved = (fixedCashOn(chargesRateOnBranch) + target - shippingCharged * (1 - order)) / coeff;
    return Math.max(0, solved);
  };

  /**
   * Pick the side of the cliff a solved price actually belongs to.
   *
   * The flat branch only owns an answer that lands below the threshold; the
   * percentage branch owns everything else. Exactly one of them always does,
   * because the fee steps *up* at the threshold (Poshmark: $2.95 becomes 20%
   * of $15, i.e. $3.00), so a target the flat side cannot reach below the
   * cliff is one the percentage side reaches only above it. Without a cliff
   * this is one call with the same arithmetic as before.
   */
  const solveOnCliff = (onBranch) => {
    if (!hasFeeCliff) return onBranch(true);
    const flatSide = onBranch(false);
    if (flatSide !== null && commissionBaseAt(flatSide) < commissionThreshold) return flatSide;
    return onBranch(true);
  };

  const breakEvenPrice = solveOnCliff((onBranch) => soldPriceOnBranch(0, onBranch));
  // Profit already carries the amortized plan share. Adding it back answers
  // "how many whole sales of this item recover the monthly fee?" — 0 when
  // there is no plan, null when the unit economics cannot recover it.
  const profitBeforeSubscription = profit + subscriptionShare;
  const ordersToCoverPlan = monthlyFee > 0 && profitBeforeSubscription > 0
    ? Math.ceil(monthlyFee / profitBeforeSubscription)
    : monthlyFee > 0 ? null : 0;

  // Expected value of one listing attempt once some share of orders come back.
  // A completed sale keeps `profit`. A return refunds the buyer, may refund a
  // share of percentage and fixed payment fees, and still costs outbound
  // postage, packaging, fulfilment, return postage, the listing / plan share,
  // and any unit that cannot be sold again. Listing fees and the monthly-plan
  // share are treated as not refunded — that is how the major channels bill.
  const returnRate = ratePercent(channel.returnRate, `${label} return rate`, 0);
  const returnShippingCost = number(channel.returnShippingCost, `${label} return shipping`, 0);
  const resellableRate = ratePercent(channel.resellableRate, `${label} still-sellable rate`, 100);
  const feeRefundRate = ratePercent(channel.feeRefundRate, `${label} fee refund rate`, 100);
  const returnedShare = returnRate / 100;
  const feeRefundShare = feeRefundRate / 100;
  const refundableFees = fees.commission + fees.payment + fees.ads;
  const keptFeesOnReturn = fees.listing + fees.subscription + refundableFees * (1 - feeRefundShare);
  const spentRegardless = packagingCost + otherCost + shippingCost + fulfilmentCost;
  const unsellableLoss = itemCost * (1 - resellableRate / 100);
  const returnedProfit = -keptFeesOnReturn - spentRegardless - returnShippingCost - unsellableLoss;
  const expectedProfit = (1 - returnedShare) * profit + returnedShare * returnedProfit;
  const returnDrag = profit - expectedProfit;

  // expectedProfit is linear in the item price once shipping charged is held
  // constant, so break-even and a target expected profit have a closed form.
  // Commission-on-item (Reverb) and commission-on-order (everyone else) both
  // land in the same shape: the sold-sale price coefficient above, and the
  // weighted revCoeff below once returns are folded in. When the return rate
  // is zero this collapses to the sold-sale break-even already on
  // `breakEvenPrice`. Both are per branch, for the cliff reason above.
  const listingAndSub = fees.listing + fees.subscription;

  /**
   * The two coefficients of `expectedProfit(price)` on one side of a fee
   * cliff, so `expectedProfit = revCoeff * price + expectedConstant`.
   *
   * A flat commission below the cliff behaves like the fixed payment fee in
   * both places it appears: it is cash to recover on a sold sale (already
   * inside `fixedCashOn`), and it is a fee the channel keeps its unrefunded
   * share of when the item comes back. It carries no price coefficient,
   * which is exactly why the cliff cannot be folded into a rate.
   */
  const expectedCoeffsOn = (chargesRateOnBranch) => {
    const { orderRate: order, itemRate: item } = branchRates(chargesRateOnBranch);
    const flat = flatCommissionOn(chargesRateOnBranch);
    return {
      revCoeff: (1 - returnedShare) * (1 - order - item)
        - returnedShare * (1 - feeRefundShare) * (item + order),
      expectedConstant: (1 - returnedShare) * (shippingCharged * (1 - order) - fixedCashOn(chargesRateOnBranch))
        + returnedShare * (
          -listingAndSub
          - (1 - feeRefundShare) * (order * shippingCharged + paymentFixed + flat)
          - spentRegardless
          - returnShippingCost
          - unsellableLoss
        ),
    };
  };
  const { revCoeff, expectedConstant } = expectedCoeffsOn(chargesRate);

  /**
   * Item price at which the *expected* keep after returns equals `target`,
   * solved on one side of a fee cliff. Null when the rates leave no
   * reachable price.
   */
  const expectedPriceOnBranch = (target, chargesRateOnBranch) => {
    const coeffs = expectedCoeffsOn(chargesRateOnBranch);
    if (coeffs.revCoeff <= 0) return null;
    return Math.max(0, (target - coeffs.expectedConstant) / coeffs.revCoeff);
  };

  const expectedBreakEvenPrice = solveOnCliff((onBranch) => expectedPriceOnBranch(0, onBranch));

  // ---------------------------------------------------------------------
  // Shelf time: what a *listing* is worth, not what a sale is worth.
  //
  // Everything above answers "if this item sells here, what do I keep". That
  // is not the seller's question when the same item can go in more than one
  // place, because the channels do not sell it equally often or equally
  // quickly. A channel with the best keep and a 20% sell-through can be worth
  // less per listing than a worse-paying channel that clears the item in a
  // fortnight, and the fee table cannot show that.
  //
  // The overlay costs a listing three things the sale-side arithmetic misses:
  //   - listing fees charged again every renewal cycle while it sits,
  //   - the cash tied up in the item for as long as it is unsold,
  //   - the chance it never sells inside the horizon at all.
  // Sale-side costs (postage, packaging, fulfilment) are not double counted:
  // they are already inside `profit` / `expectedProfit` and only occur on the
  // sold branch.
  const horizonDays = number(shared.horizonDays, "How long you will leave it listed", 90);
  if (horizonDays <= 0) throw new Error("How long you will leave it listed must be more than zero days");
  const capitalCostPct = number(shared.capitalCostPct, "Annual cost of the cash tied up", 0);
  const unsoldRecoveryPct = ratePercent(shared.unsoldRecoveryPct, "Value kept if it does not sell", 100);
  const sellThroughPct = ratePercent(channel.sellThroughPct, `${label} sell-through rate`, 100);
  const shelfDaysToSell = number(daysToSellInput, `${label} days to sell`, 0);
  const listingRenewalDays = number(channel.listingRenewalDays, `${label} listing renewal days`, 0);

  // A listing cannot sell after you have taken it down, so a channel whose
  // typical time to sale is past the horizon effectively sells on the last day.
  const soldDays = Math.min(shelfDaysToSell, horizonDays);
  const listingCycles = (days) =>
    listingRenewalDays > 0 ? Math.max(1, Math.ceil(days / listingRenewalDays)) : 1;
  // Only the item cost is capital tied up while it waits — packaging, postage
  // and fulfilment are not spent until it sells.
  const holdingCost = (days) => (itemCost * (capitalCostPct / 100) * days) / 365;

  // The returns overlay is part of what a sale is worth, so the shelf-time
  // layer sits on whichever keep the caller is ranking on.
  const soldKeep = shared.includeReturns === false ? profit : expectedProfit;
  const renewalsWhileSelling = perListingFee * (listingCycles(soldDays) - 1);
  const soldValue = soldKeep - renewalsWhileSelling - holdingCost(soldDays);
  const unsoldValue = -perListingFee * listingCycles(horizonDays)
    - holdingCost(horizonDays)
    - itemCost * (1 - unsoldRecoveryPct / 100);

  const sellShare = sellThroughPct / 100;
  const listedValue = sellShare * soldValue + (1 - sellShare) * unsoldValue;
  // Days of shelf the listing occupies on average, sold or not. Turning the
  // per-listing figure into a rate is what lets a fast cheap channel outrank a
  // slow rich one on the same inventory dollar.
  const shelfDays = sellShare * soldDays + (1 - sellShare) * horizonDays;
  const valuePer30Days = shelfDays > 0 ? (listedValue / shelfDays) * 30 : listedValue;

  const velocity = {
    sellThroughPct,
    daysToSell: shelfDaysToSell,
    listingRenewalDays,
    horizonDays,
    soldDays,
    shelfDays,
    soldValue,
    unsoldValue,
    listedValue,
    valuePer30Days,
    renewalsWhileSelling,
    unsoldListingFees: perListingFee * listingCycles(horizonDays),
    holdingCostIfUnsold: holdingCost(horizonDays),
    // What the sell-through assumption costs versus a channel that always
    // sells at `daysToSell`. This is the shelf-time analogue of `returnDrag`.
    shelfDrag: soldKeep - listedValue,
    /**
     * Sell-through this channel would need to earn `target` per 30 days of
     * shelf time — the "how often would it have to sell here to catch up"
     * question, and the shelf-time analogue of `priceToMatchBest`.
     *
     * Both sides of the rate move with the sell-through share: selling more
     * often raises the value of a listing *and* shortens the shelf it
     * occupies. Writing rate(s) = 30·(u + s(v−u)) / (H + s(D−H)) and solving
     * for s gives the closed form below. Null when no share in 0–100% reaches
     * the target, which is the honest answer for a channel that cannot catch
     * the leader however reliably it sells.
     */
    sellThroughForRate(target) {
      const wanted = Number(target);
      if (!Number.isFinite(wanted)) throw new Error("Target value per 30 days must be a number");
      const denominator = 30 * (soldValue - unsoldValue) - wanted * (soldDays - horizonDays);
      if (denominator === 0) return null;
      const share = (wanted * horizonDays - 30 * unsoldValue) / denominator;
      if (!Number.isFinite(share) || share < 0 || share > 1) return null;
      return share * 100;
    },
  };

  return {
    id: channel.id ?? null,
    label,
    note: channel.note ?? null,
    price,
    shippingCharged,
    revenue,
    fees,
    feeTotal,
    cashInvested,
    profit,
    expectedProfit,
    returnedProfit,
    returnDrag,
    returnRate,
    returnShippingCost,
    resellableRate,
    feeRefundRate,
    expectedBreakEvenPrice,
    velocity,
    margin: revenue === 0 ? 0 : (profit / revenue) * 100,
    expectedMargin: revenue === 0 ? 0 : (expectedProfit / revenue) * 100,
    // Undefined rather than infinite when nothing was invested (a giveaway, a
    // digital item with no per-unit cost).
    roi: cashInvested === 0 ? null : (profit / cashInvested) * 100,
    percentRate: percentRate * 100,
    fixedCash,
    ordersToCoverPlan,
    expectedMonthlySales,
    // When volume is at least one, the per-sale profit already carries its
    // share of the monthly plan, so multiplying recovers the plan once.
    // At zero volume the plan was not amortized, so subtract it here.
    monthlyProfit: expectedMonthlySales >= 1
      ? profit * expectedMonthlySales
      : -unamortizedMonthlyFee,
    breakEvenPrice,
    daysToSell,
    // Cash this sale leaves you per day it sits unsold. Null when the seller
    // has not given a pace — inventing one would rank channels on a guess
    // they never entered. 30-day month is a planning figure, not a calendar.
    profitPerDay: daysToSell === null ? null : profit / daysToSell,
    monthlyProfitAtVelocity: daysToSell === null ? null : profit * (30 / daysToSell),
    // How many times a year the same cash completes this buy-sell loop. Stated
    // as a turnover count rather than an annualised percentage on purpose: a
    // three-day flip annualises to four figures, which is arithmetically true,
    // reads as a promise, and would be the one dishonest number on the page.
    // "Your cash goes round 122 times a year" is the same fact without the
    // implied compounding.
    cashTurnsPerYear: daysToSell === null ? null : 365 / daysToSell,
    /**
     * Item price this channel needs, holding shipping charged constant, to
     * clear `targetProfit`. This is the number that turns a comparison into a
     * decision: "to keep the same $12.40, this channel has to be listed at
     * $54.80."
     */
    priceForProfit(targetProfit) {
      const target = Number(targetProfit);
      if (!Number.isFinite(target)) throw new Error("Target profit must be a number");
      const solved = solveOnCliff((onBranch) => soldPriceOnBranch(target, onBranch));
      if (solved === null) {
        throw new Error(`${label}: target profit cannot be solved at these fee rates`);
      }
      return solved;
    },
    /**
     * Item price this channel needs so the *expected* keep after returns
     * matches `targetProfit`. Same closed form as sold `priceForProfit`
     * when the return rate is zero.
     */
    priceForExpectedProfit(targetProfit) {
      const target = Number(targetProfit);
      if (!Number.isFinite(target)) throw new Error("Target profit must be a number");
      const solved = solveOnCliff((onBranch) => expectedPriceOnBranch(target, onBranch));
      if (solved === null) {
        throw new Error(`${label}: expected profit cannot be solved at these return and fee rates`);
      }
      return solved;
    },
  };
}

/**
 * Rank every channel on the same item and say what each one costs relative to
 * the best. `channels` are preset-shaped objects; anything a seller edited is
 * already on them, anything they left alone falls back to `shared`. A channel
 * carrying `enabled: false` is one the seller has switched off — it is left
 * out of the ranking entirely rather than shown as an unreachable option.
 */
export function compareChannels(channels, shared = {}) {
  if (!Array.isArray(channels) || channels.length === 0) {
    throw new Error("At least one channel is required");
  }
  const active = channels.filter((channel) => channel?.enabled !== false);
  if (active.length === 0) throw new Error("Switch on at least one channel to compare");
  const results = active.map((channel) => calculateChannel(channel, shared));
  // A seller-entered profit goal, shared across every channel: "what would
  // each one have to charge to leave me exactly this much?" Blank, null or
  // absent means the question was not asked, so the field on every result
  // stays null rather than solving for a target nobody gave.
  const hasTargetProfit = shared.targetProfit !== undefined && shared.targetProfit !== null && shared.targetProfit !== "";
  const targetProfit = hasTargetProfit ? number(shared.targetProfit, "Target profit") : null;
  // Rank on expected keep after returns unless the seller has turned that
  // overlay off. Sold-sale profit is still on every row so the table can
  // show the flip: a channel can win on a completed sale and lose once
  // returns are counted.
  const includeReturns = shared.includeReturns !== false;
  const score = (result) => (includeReturns ? result.expectedProfit : result.profit);
  const best = results.reduce((winner, result) => (score(result) > score(winner) ? result : winner));
  const withPace = results.filter((result) => result.profitPerDay !== null);
  const bestOnVelocity = withPace.length === 0
    ? null
    : withPace.reduce((winner, result) => (
      result.profitPerDay > winner.profitPerDay ? result : winner
    ));

  // Ranking by profit stays the default: it is the question people arrive with.
  // `rankBy: "profitPerDay"` re-sorts on what the cash earns while it waits.
  // A channel with no holding period sorts last there rather than winning on an
  // unknown, and ties fall back to the profit score (expected keep after
  // returns, unless that overlay is off) so the order stays stable.
  const rankBy = shared.rankBy === "profitPerDay" ? "profitPerDay" : "profit";
  const perDay = (result) => (result.profitPerDay === null ? -Infinity : result.profitPerDay);
  const order = rankBy === "profitPerDay"
    ? (a, b) => perDay(b) - perDay(a) || score(b) - score(a)
    : (a, b) => score(b) - score(a);
  const ranked = [...results].sort(order);
  const rankById = new Map(ranked.map((result, index) => [result, index + 1]));
  const bestScore = score(best);

  // Second, independent ranking: what one listing is worth per 30 days of
  // shelf time, which counts how often and how fast each channel actually
  // sells. It is reported alongside the keep ranking rather than replacing it
  // — the two disagreeing is the finding, not a problem to hide behind a
  // toggle. Ranking on the rate rather than the per-listing total is what
  // makes a fast channel win: the same inventory dollar turns more often.
  const shelfScore = (result) => result.velocity.valuePer30Days;
  const shelfRanked = [...results].sort((a, b) => shelfScore(b) - shelfScore(a));
  const shelfRankById = new Map(shelfRanked.map((result, index) => [result, index + 1]));
  const shelfBest = shelfRanked[0];
  const shelfBestScore = shelfScore(shelfBest);

  // Third ranking: expected monthly cash when channel volumes differ. A
  // cheaper-per-sale channel can lose the month when another simply sells
  // more units. Empty per-channel volume falls back to shared monthlyOrders
  // so existing comparisons stay unchanged.
  const bestMonthly = results.reduce(
    (winner, result) => (result.monthlyProfit > winner.monthlyProfit ? result : winner),
  );
  const monthlyRanked = [...results].sort((a, b) => b.monthlyProfit - a.monthlyProfit);
  const monthlyRankByResult = new Map(monthlyRanked.map((result, index) => [result, index + 1]));
  const volumesDiffer = results.some(
    (result) => result.expectedMonthlySales !== results[0].expectedMonthlySales,
  );

  // The winner on speed, computed whichever way the table is sorted, because
  // the interesting case is the two disagreeing: a channel that nets less per
  // sale but turns the cash over faster.
  const timed = results.filter((result) => result.profitPerDay !== null);
  const fastestReturn = timed.length
    ? timed.reduce((winner, result) => (result.profitPerDay > winner.profitPerDay ? result : winner))
    : null;

  return {
    results: results.map((result) => ({
      ...result,
      rank: rankById.get(result),
      monthlyRank: monthlyRankByResult.get(result),
      isBest: result === best,
      isBestMonthly: result === bestMonthly,
      isBestOnVelocity: result === bestOnVelocity,
      // Negative or zero for the velocity winner; for everyone else, the
      // cash-per-day this channel gives up against the fastest earner.
      gapVsBestPerDay: bestOnVelocity === null || result.profitPerDay === null
        ? null
        : bestOnVelocity.profitPerDay - result.profitPerDay,
      shelfRank: shelfRankById.get(result),
      isShelfBest: result === shelfBest,
      // Cash per 30 days of shelf this channel gives up against the fastest
      // earner, and the sell-through it would need to close that gap.
      shelfGapVsBest: shelfBestScore - shelfScore(result),
      sellThroughToMatchBest: result === shelfBest
        ? null
        : result.velocity.sellThroughForRate(shelfBestScore),
      // Negative or zero for the winner; for everyone else, the cash this
      // channel gives up on the same item (sold, or expected after returns).
      gapVsBest: bestScore - score(result),
      monthlyGapVsBest: bestMonthly.monthlyProfit - result.monthlyProfit,
      // What this channel would have to charge to match the winner. Null on
      // the winner itself, where the question is meaningless.
      priceToMatchBest: result === best
        ? null
        : includeReturns
          ? result.priceForExpectedProfit(best.expectedProfit)
          : result.priceForProfit(best.profit),
      // Item price this channel needs to keep the seller's own target,
      // holding shipping charged constant. Solved on the sold-sale price
      // equation (not the after-returns one) so the number answers "if it
      // sells here, what would I have to charge" — the same question the
      // seller is asking, independent of the returns overlay.
      priceForTargetProfit: targetProfit === null ? null : result.priceForProfit(targetProfit),
    })),
    ranked: ranked.map((result) => result.label),
    rankBy,
    includeReturns,
    best: {
      id: best.id,
      label: best.label,
      profit: bestScore,
      soldProfit: best.profit,
      expectedProfit: best.expectedProfit,
      margin: includeReturns ? best.expectedMargin : best.margin,
    },
    // Null when no active channel has a holding period to divide by.
    fastestReturn: fastestReturn && {
      id: fastestReturn.id,
      label: fastestReturn.label,
      profit: fastestReturn.profit,
      daysToSell: fastestReturn.daysToSell,
      profitPerDay: fastestReturn.profitPerDay,
      cashTurnsPerYear: fastestReturn.cashTurnsPerYear,
    },
    // True only when the extra column changes the answer — the one moment this
    // feature is worth a seller's attention. It also requires the profit winner
    // to have a holding period of its own: "sells faster than" is not a
    // comparison that can be made against an unknown, and claiming it would
    // rank a channel the seller never timed.
    speedChangesTheAnswer:
      Boolean(fastestReturn) && fastestReturn.id !== best.id && best.profitPerDay !== null,
    bestMonthly: {
      id: bestMonthly.id,
      label: bestMonthly.label,
      monthlyProfit: bestMonthly.monthlyProfit,
      expectedMonthlySales: bestMonthly.expectedMonthlySales,
    },
    bestOnVelocity: bestOnVelocity === null ? null : {
      id: bestOnVelocity.id,
      label: bestOnVelocity.label,
      profitPerDay: bestOnVelocity.profitPerDay,
      daysToSell: bestOnVelocity.daysToSell,
      monthlyProfitAtVelocity: bestOnVelocity.monthlyProfitAtVelocity,
    },
    /**
     * The shelf-time verdict. `agrees` is the headline: when the channel that
     * pays best per sale is not the channel that earns most per month of
     * shelf, the seller is choosing between margin and turnover, and the page
     * says so rather than picking for them.
     */
    shelf: {
      id: shelfBest.id,
      label: shelfBest.label,
      valuePer30Days: shelfBestScore,
      listedValue: shelfBest.velocity.listedValue,
      shelfDays: shelfBest.velocity.shelfDays,
      sellThroughPct: shelfBest.velocity.sellThroughPct,
      horizonDays: shelfBest.velocity.horizonDays,
      agrees: shelfBest === best,
      ranked: shelfRanked.map((result) => result.label),
      spread: shelfBestScore - shelfScore(shelfRanked[shelfRanked.length - 1]),
    },
    // How much the channel choice is worth on this one item if it sells
    // everywhere. `shelf.spread` is the same question once sell-through and
    // time to sale are counted. `monthlySpread` is the same question once
    // each channel's expected volume is counted.
    spread: bestScore - score(ranked[ranked.length - 1]),
    monthlySpread: bestMonthly.monthlyProfit - monthlyRanked[monthlyRanked.length - 1].monthlyProfit,
    volumesDiffer,
    // The decision the fee-only ranking cannot make: a cheaper-per-sale
    // channel loses the month when another one simply sells more units.
    rankingsDiverge: best.id !== bestMonthly.id,
  };
}

cli.mjs.text:
#!/usr/bin/env node
// Which channel for each item in a spreadsheet, in a terminal.
//
//   node cli.mjs items.csv                      # best channel per item, and what routing them is worth
//   node cli.mjs items.csv --channels ebay,poshmark,mercari
//   node cli.mjs items.csv --csv > routed.csv   # one row per item and channel
//   node cli.mjs items.csv --json
//   node cli.mjs --example
//
// Same arithmetic as the web page (calc.mjs, the same channel presets): every
// item goes through every channel that is switched on. Zero dependencies, no
// network: prices and costs never leave the machine. Illustrative fee
// assumptions, not advice; replace the rates with your own before relying on it.

import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import process from "node:process";
import { CHANNEL_PRESETS, compareChannels } from "./calc.mjs";

const USAGE = `Rank every selling channel for each item in a CSV and show what routing items to their best channel is worth.

Usage:
  node cli.mjs [options] <items.csv | ->

Input: a header row, then one item per line. Columns (any order, case-insensitive):
  item (or name, title, sku)   a label for the row (optional)
  price                        what you would list it for (required)
  itemCost (or cost)           what the item cost you (required)
  shippingCharged              postage the buyer pays you (default 0)
  shippingCost                 postage you pay (default 0)
  packagingCost, otherCost     per-order extras (default 0)

Options:
  --channels <ids>       compare exactly these channels, e.g. ebay,etsy,poshmark
  --also <ids>           add channels that are off by default (e.g. poshmark,stockx), or local
                         (a fee-free direct sale, left out because it would win every item)
  --monthly-orders <n>   orders a month, to spread monthly plans over (default 100)
  --rank-by <profit|profitPerDay>   what "best" means (default profit)
  --no-returns           rank on the sold-sale profit, ignoring each channel's return rate
  --list-channels        print the channel ids and whether each is on by default
  --csv                  one row per item and channel
  --json                 the full result as JSON
  --example              run on built-in invented items
  -h, --help             this message

Fees and return rates are illustrative presets, the same as the web page's. The tool does
not know your account's rates, so edit calc.mjs or use the page to change one. Not financial advice.
`;

const ALIASES = {
  item: "label", name: "label", title: "label", sku: "label", label: "label",
  price: "price", cost: "itemCost", itemcost: "itemCost",
  shippingcharged: "shippingCharged", shippingcost: "shippingCost",
  packagingcost: "packagingCost", othercost: "otherCost",
};
const NUMERIC = ["price", "itemCost", "shippingCharged", "shippingCost", "packagingCost", "otherCost"];

export function sampleItems() {
  return [
    "item,price,itemCost,shippingCharged,shippingCost,packagingCost",
    "Vintage denim jacket,48,14,0,0,0.5",
    "Handmade ceramic mug,32,9,5,5.2,1.5",
    "Used paperback bundle,22,4,4,4.1,0.8",
    "Retro handheld console,95,40,8,7.5,2",
    "Phone case (new),12,3,3.5,3.2,0.4",
  ].join("\n") + "\n";
}

function splitLine(line) {
  const cells = [];
  let cur = "", quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') { cur += '"'; i++; }
      else if (ch === '"') quoted = false;
      else cur += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === "," || ch === "\t") { cells.push(cur.trim()); cur = ""; }
    else cur += ch;
  }
  cells.push(cur.trim());
  return cells;
}

export function parseItems(text) {
  const lines = String(text).replace(/^﻿/, "").split(/\r?\n/).filter((l) => l.trim() !== "");
  if (lines.length < 2) return { error: "Give a header row and at least one item." };
  const header = splitLine(lines[0]).map((h) => ALIASES[h.toLowerCase().replace(/[\s_-]/g, "")] ?? null);
  if (!header.includes("price") || !header.includes("itemCost")) {
    return { error: "The header needs at least a price column and an itemCost (or cost) column." };
  }
  const rows = [], warnings = [];
  lines.slice(1).forEach((line, index) => {
    const cells = splitLine(line);
    const row = { label: `Item ${index + 1}` };
    for (let c = 0; c < header.length; c++) {
      const key = header[c], raw = cells[c] ?? "";
      if (!key || raw === "") continue;
      if (key === "label") { row.label = raw; continue; }
      const n = Number(raw.replace(/^\$/, ""));
      if (!Number.isFinite(n) || n < 0) { row.bad = `${key} "${raw}" is not a non-negative number`; break; }
      row[key] = n;
    }
    if (!row.bad && row.price === undefined) row.bad = "no price";
    if (!row.bad && row.itemCost === undefined) row.bad = "no itemCost";
    if (row.bad) warnings.push(`Skipped "${row.label}": ${row.bad}.`);
    else rows.push(row);
  });
  if (rows.length === 0) return { error: `No usable items. ${warnings.join(" ")}`.trim() };
  return { rows, warnings };
}

export function parseArgs(argv) {
  const o = { file: null, channels: null, also: [], monthlyOrders: 100, rankBy: "profit", returns: true,
    csv: false, json: false, example: false, help: false, list: false };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "-h" || a === "--help") o.help = true;
    else if (a === "--csv") o.csv = true;
    else if (a === "--json") o.json = true;
    else if (a === "--example") o.example = true;
    else if (a === "--list-channels") o.list = true;
    else if (a === "--no-returns") o.returns = false;
    else if (["--channels", "--also", "--monthly-orders", "--rank-by"].includes(a)) {
      const v = argv[++i];
      if (v === undefined) return { error: `${a} needs a value.` };
      if (a === "--channels") o.channels = v.split(",").map((s) => s.trim()).filter(Boolean);
      else if (a === "--also") o.also = v.split(",").map((s) => s.trim()).filter(Boolean);
      else if (a === "--rank-by") {
        if (v !== "profit" && v !== "profitPerDay") return { error: "--rank-by is profit or profitPerDay." };
        o.rankBy = v;
      } else {
        const n = Number(v);
        if (!Number.isFinite(n) || n <= 0) return { error: "--monthly-orders must be a positive number." };
        o.monthlyOrders = n;
      }
    } else if (a === "-" || !a.startsWith("-")) {
      if (o.file) return { error: "Give one items file." };
      o.file = a;
    } else return { error: `Unknown option ${a}. Try --help.` };
  }
  return o;
}

function pickChannels(a) {
  const ids = new Set(CHANNEL_PRESETS.map((p) => p.id));
  for (const id of [...(a.channels ?? []), ...a.also]) {
    if (!ids.has(id)) return { error: `Unknown channel "${id}". Try --list-channels.` };
  }
  const want = a.channels ? new Set(a.channels) : new Set(CHANNEL_PRESETS.filter((p) => p.enabled !== false && p.id !== "local").map((p) => p.id));
  for (const id of a.also) want.add(id);
  const chosen = CHANNEL_PRESETS.filter((p) => want.has(p.id)).map((p) => ({ ...p, enabled: true }));
  if (chosen.length === 0) return { error: "Choose at least one channel." };
  // "other" is a blank row for the page; with no rates it would win every item.
  if (chosen.some((c) => c.id === "other")) return { error: "The blank 'other' channel has no rates; use the web page to fill it in." };
  return { channels: chosen };
}

const r2 = (n) => Math.round(n * 100) / 100;
export const money = (n) => `${n < 0 ? "-" : ""}$${Math.abs(n).toFixed(2)}`;

export function analyze(items, channels, opts = {}) {
  const includeReturns = opts.includeReturns !== false;
  const keep = (r) => (includeReturns ? r.expectedProfit : r.profit);
  const rows = [], errors = [];
  const totals = Object.fromEntries(channels.map((c) => [c.id, { label: c.label, keep: 0, items: 0 }]));
  let routed = 0;
  const wins = {};
  for (const item of items) {
    const { label, ...rest } = item;
    let cmp;
    try {
      cmp = compareChannels(channels, { monthlyOrders: opts.monthlyOrders ?? 100, rankBy: opts.rankBy ?? "profit", includeReturns, ...rest });
    } catch (e) {
      errors.push(`Skipped "${label}": ${e.message}`);
      continue;
    }
    const sorted = [...cmp.results].sort((x, y) => x.rank - y.rank);
    const best = sorted[0], next = sorted[1] ?? null;
    for (const r of cmp.results) { totals[r.id].keep += keep(r); totals[r.id].items += 1; }
    routed += keep(best);
    wins[best.id] = (wins[best.id] ?? 0) + 1;
    rows.push({
      label, best: best.id, bestLabel: best.label, keep: r2(keep(best)),
      runnerUp: next ? next.label : null, margin: next ? r2(keep(best) - keep(next)) : null,
      channels: sorted.map((r) => ({ id: r.id, label: r.label, rank: r.rank, profit: r2(r.profit), expectedProfit: r2(r.expectedProfit) })),
    });
  }
  const n = rows.length;
  const single = Object.entries(totals)
    .filter(([, t]) => t.items === n && n > 0)
    .map(([id, t]) => ({ id, label: t.label, keep: r2(t.keep) }))
    .sort((x, y) => y.keep - x.keep);
  return {
    rows, errors, includeReturns,
    routedKeep: r2(routed),
    bestSingleChannel: single[0] ?? null,
    uplift: single[0] ? r2(routed - single[0].keep) : null,
    singleChannel: single,
    wins: Object.entries(wins).map(([id, count]) => ({ id, label: totals[id].label, count })).sort((x, y) => y.count - x.count),
  };
}

export function render(r) {
  const out = [];
  const basis = r.includeReturns ? "expected keep after returns" : "profit on a completed sale";
  for (const row of r.rows) {
    const gap = row.margin === null ? "" : ` (${money(row.margin)} ahead of ${row.runnerUp})`;
    out.push(`${row.label}: ${row.bestLabel}, ${money(row.keep)}${gap}`);
  }
  out.push("");
  if (r.rows.length) {
    out.push(`Routing each of ${r.rows.length} item(s) to its best channel keeps ${money(r.routedKeep)} (${basis}, one unit each).`);
    if (r.bestSingleChannel) {
      out.push(`Listing everything on ${r.bestSingleChannel.label} alone, the best single channel, keeps ${money(r.bestSingleChannel.keep)}: routing adds ${money(r.uplift)}.`);
    }
    out.push(`Channels that won an item: ${r.wins.map((w) => `${w.label} ${w.count}`).join(", ")}.`);
    out.push("Fees and return rates are illustrative presets; use your own before acting on this.");
  }
  for (const e of r.errors) out.push(`Note: ${e}`);
  return out.join("\n") + "\n";
}

const cell = (v) => (/[",\n\r]/.test(String(v)) ? `"${String(v).replaceAll('"', '""')}"` : String(v));
export function reportCsv(r) {
  const lines = ["item,channel,rank,is_best,profit,expected_profit"];
  for (const row of r.rows) {
    for (const c of row.channels) {
      lines.push([row.label, c.label, c.rank, c.id === row.best ? "yes" : "", c.profit.toFixed(2), c.expectedProfit.toFixed(2)].map(cell).join(","));
    }
  }
  return lines.join("\n") + "\n";
}

export async function main(argv, io = { read: (f) => readFile(f, "utf8"), stdin: () => readFile(0, "utf8") }) {
  const a = parseArgs(argv);
  if (a.error) return { code: 2, err: a.error + "\n" };
  if (a.help) return { code: 0, out: USAGE };
  if (a.list) {
    return { code: 0, out: CHANNEL_PRESETS.map((p) => `${p.id.padEnd(22)} ${p.label}${p.enabled === false || p.id === "local" ? "  (off by default)" : ""}`).join("\n") + "\n" };
  }
  let text;
  if (a.example) text = sampleItems();
  else if (!a.file) return { code: 2, err: "Give an items file, '-' for stdin, or --example. Try --help.\n" };
  else try { text = a.file === "-" ? await io.stdin() : await io.read(a.file); } catch (e) { return { code: 2, err: `Cannot read ${a.file}: ${e.message}\n` }; }
  const parsed = parseItems(text);
  if (parsed.error) return { code: 2, err: parsed.error + "\n" };
  const picked = pickChannels(a);
  if (picked.error) return { code: 2, err: picked.error + "\n" };
  const r = analyze(parsed.rows, picked.channels, { monthlyOrders: a.monthlyOrders, rankBy: a.rankBy, includeReturns: a.returns });
  r.errors.unshift(...parsed.warnings);
  if (r.rows.length === 0) return { code: 2, err: `No item could be compared. ${r.errors.join(" ")}\n` };
  return { code: 0, out: a.json ? JSON.stringify(r, null, 2) + "\n" : a.csv ? reportCsv(r) : render(r) };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const res = await main(process.argv.slice(2));
  if (res.out) process.stdout.write(res.out);
  if (res.err) process.stderr.write(res.err);
  process.exitCode = res.code;
}

export.mjs.text:
// CSV export for a calculated comparison. This module accepts derived results,
// not saved inputs, so it cannot accidentally include local usage data.

const HEADERS = [
  "rank",
  "channel",
  "price",
  "fees",
  "profit",
  "expected_profit",
  "return_drag",
  "margin_percent",
  "return_on_cash_percent",
  "monthly_profit",
  "days_to_sell",
  "profit_per_day",
  "monthly_profit_at_velocity",
  "break_even_price",
  "orders_to_cover_plan",
  "price_to_match_best",
];

function escapeCell(value) {
  const text = value === null || value === undefined ? "" : String(value);
  return /[",\n\r]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

function money(value) {
  return Number.isFinite(value) ? value.toFixed(2) : "";
}

function percent(value) {
  return Number.isFinite(value) ? value.toFixed(1) : "";
}

function count(value) {
  return Number.isFinite(value) ? String(value) : "";
}

export function comparisonCsv(comparison) {
  if (!comparison || !Array.isArray(comparison.results)) {
    throw new Error("A calculated comparison is required");
  }
  const rows = comparison.results
    .slice()
    .sort((a, b) => a.rank - b.rank)
    .map((result) => [
      result.rank,
      result.label,
      money(result.price),
      money(result.feeTotal),
      money(result.profit),
      money(result.expectedProfit),
      money(result.returnDrag),
      percent(result.margin),
      percent(result.roi),
      money(result.monthlyProfit),
      count(result.daysToSell),
      money(result.profitPerDay),
      money(result.monthlyProfitAtVelocity),
      money(result.breakEvenPrice),
      count(result.ordersToCoverPlan),
      money(result.priceToMatchBest),
    ]);
  return [HEADERS, ...rows].map((row) => row.map(escapeCell).join(",")).join("\n") + "\n";
}

handoff-arrival.check.mjs.text:
// Browser check: every handoff link lands with the values it carried.
//
// handoff.test.mjs proves the field names match each target's own field list.
// This opens each target page in Chromium and reads the inputs back, so a
// target that renames an input id or stops reading the URL fragment fails here.
//
//   (cd ventures && python3 -m http.server 8765) &
//   PLAYWRIGHT_MODULE=/path/to/node_modules node handoff-arrival.check.mjs
//
// Not a *.test.mjs file on purpose: it needs a browser and a server, which
// `node --test` runs elsewhere do not have.
import { createRequire } from 'node:module';
import { handoffUrl, HANDOFFS } from './handoff.mjs';

const base = process.env.BASE_URL ?? 'http://localhost:8765';
const require = createRequire(`${process.env.PLAYWRIGHT_MODULE ?? process.cwd() + '/node_modules'}/`);
const { chromium } = require('playwright');

const shared = { price: 40, shippingCharged: 6, shippingCost: 5.2, itemCost: 12, packagingCost: 1.1, otherCost: 0.9 };
const browser = await chromium.launch(
  process.env.CHROMIUM_PATH ? { executablePath: process.env.CHROMIUM_PATH } : {},
);
let failed = 0;
for (const entry of HANDOFFS) {
  const page = await (await browser.newContext()).newPage(); // fresh storage per target
  const url = `${base}/where-to-sell-calculator/${handoffUrl(entry.channel, shared)}`;
  await page.goto(url);
  await page.waitForTimeout(300);
  const got = await page.evaluate(() =>
    Object.fromEntries([...document.querySelectorAll('input,select')].filter((el) => el.id).map((el) => [el.id, el.value])),
  );
  const bad = [...new URLSearchParams(url.split('#')[1])].filter(([k, v]) => got[k] === undefined || Number(got[k]) !== Number(v));
  if (bad.length) failed += 1;
  console.log(bad.length ? `FAIL ${entry.slug} ${JSON.stringify(bad)}` : `ok   ${entry.slug}`);
}
await browser.close();
process.exit(failed ? 1 : 0);

handoff-return.check.mjs.text:
// Browser check, the reverse direction: every channel calculator's own
// "compare on other channels" link lands here with its item and its channel on.
//
// handoff-arrival.check.mjs covers where-to-sell -> channel calculator. This
// covers channel calculator -> where-to-sell: each venture's
// to-where-to-sell.mjs builds a link, this opens it in Chromium and reads back
// the shared inputs and the channel's "Compare this channel" box.
//
//   (cd ventures && python3 -m http.server 8765) &
//   PLAYWRIGHT_MODULE=/path/to/node_modules node handoff-return.check.mjs
//
// Not a *.test.mjs file on purpose: it needs a browser and a server.
import { createRequire } from 'node:module';
import { readdirSync, existsSync } from 'node:fs';

const base = process.env.BASE_URL ?? 'http://localhost:8765';
const require = createRequire(`${process.env.PLAYWRIGHT_MODULE ?? process.cwd() + '/node_modules'}/`);
const { chromium } = require('playwright');

// Each module reads its own calculator's field names, so offer every name in use.
const item = {
  price: 40, salePrice: 40, itemPrice: 40,
  shippingCharged: 6, buyerShipping: 6,
  shippingCost: 5.2, labelCost: 5.2, sellerShippingCost: 5.2,
  itemCost: 12, costOfGoods: 12, materialCost: 12,
  packagingCost: 1.1, otherCost: 0.9,
};

const ventures = readdirSync('..').filter((d) => existsSync(`../${d}/to-where-to-sell.mjs`)).sort();
const browser = await chromium.launch(
  process.env.CHROMIUM_PATH ? { executablePath: process.env.CHROMIUM_PATH } : {},
);
let failed = 0;
for (const slug of ventures) {
  // A fresh context each time: the page saves its inputs, and a leftover from the
  // previous venture would mask a link that fails to set a field.
  const page = await (await browser.newContext()).newPage();
  const { whereToSellPayload, whereToSellUrl } = await import(`../${slug}/to-where-to-sell.mjs`);
  const payload = whereToSellPayload(item);
  const url = `${base}/${slug}/${whereToSellUrl(item)}`.replace(`/${slug}/../`, '/');
  await page.goto(url);
  await page.waitForTimeout(300);
  const got = await page.evaluate(() => ({
    inputs: Object.fromEntries([...document.querySelectorAll('input,select')].filter((el) => el.id).map((el) => [el.id, el.value])),
    enabled: Object.fromEntries([...document.querySelectorAll('input[data-enable]')].map((el) => [el.closest('details').querySelector('summary').textContent.trim(), el.checked])),
  }));
  const bad = Object.entries(payload.shared).filter(([k, v]) => Number(got.inputs[k]) !== Number(v)).map(([k]) => `input ${k}`);
  if (!Object.keys(payload.shared).length) bad.push('payload carried no item values');
  for (const channel of payload.channels.filter((c) => c.enabled)) {
    const hit = Object.entries(got.enabled).find(([label]) => label.toLowerCase().replace(/[^a-z]/g, '').includes(channel.id.replace(/[^a-z]/g, '')));
    if (!hit || !hit[1]) bad.push(`channel ${channel.id} not switched on`);
  }
  if (bad.length) failed += 1;
  console.log(bad.length ? `FAIL ${slug} ${JSON.stringify(bad)}` : `ok   ${slug}`);
}
await browser.close();
process.exit(failed ? 1 : 0);

handoff.mjs.text:
// Carry the item you just compared into the channel's own calculator.
//
// This page answers "which channel?" and stops there. The follow-up question —
// "so what does a promoted listing / free shipping / a return actually do to
// that number on eBay?" — is answered by a separate calculator in this
// portfolio with twenty-odd scenarios in it. Until now the only way through was
// to retype the item: price, postage, what you paid, packaging, everything.
// Most people do not, so the deep tool goes unused and the comparison ends at a
// ranking nobody acts on.
//
// So each channel that has a dedicated calculator *and* can accept inputs from
// a link gets a "continue with these numbers" link, built from what is on
// screen. Nothing is uploaded: this is the same in-page URL mechanism the
// "Copy share link" button already uses, and the values only ever travel
// inside the reader's own browser as they follow the link.
//
// The mapping is the fragile part. Each calculator named its inputs for its own
// niche — what this page calls `itemCost` is `costOfGoods` on eBay and
// `materialCost` on Etsy — and a name that does not match is *silently dropped*
// by the receiving decoder. The failure is a wrong number on arrival, not an
// error, which is exactly the bug `share.mjs` shipped once already (a link that
// dropped `quantity` and `targetMargin`, so the recipient computed a different
// profit than the sender saw). `handoff.test.mjs` therefore imports each
// target's own field list and asserts every name here is one it accepts.

/**
 * Channels with a deeper calculator that accepts inputs from a link.
 *
 * `fields` maps this page's shared-input id to the target's id. A channel
 * absent from this table simply gets no link — deliberately, since a link that
 * silently arrives with default numbers is worse than no link at all.
 */
export const HANDOFFS = [
  {
    channel: 'ebay',
    slug: 'ebay-fee-calculator',
    label: 'eBay fee & profit calculator',
    // What it adds: promoted listings, returns, Top Rated Plus, store
    // subscription, offers, international, and twenty more decisions.
    fields: {
      price: 'price',
      shippingCharged: 'shippingCharged',
      shippingCost: 'shippingCost',
      itemCost: 'costOfGoods',
      packagingCost: 'packagingCost',
      otherCost: 'otherCost',
    },
  },
  {
    channel: 'etsy',
    slug: 'etsy-profit-calculator',
    label: 'Etsy profit calculator',
    // Etsy has no separate packaging input; it belongs with materials, which
    // is what that field means there. Summed rather than dropped — see
    // `combine` below.
    fields: {
      price: 'price',
      shippingCharged: 'shippingCharged',
      shippingCost: 'shippingCost',
      itemCost: 'materialCost',
      otherCost: 'otherCost',
    },
    combine: { materialCost: ['itemCost', 'packagingCost'] },
  },
  {
    channel: 'amazon',
    slug: 'amazon-fba-calculator',
    label: 'Amazon FBA vs FBM calculator',
    // What it adds: the FBA-versus-FBM split this page cannot make (it prices
    // Amazon as one channel), plus size-tier fulfilment, storage by month,
    // inbound placement, returns, Low-Price FBA, coupons, Subscribe & Save,
    // Vine, and Seller Fulfilled Prime.
    //
    // `shippingCharged` has no home here and is deliberately dropped rather
    // than mapped: Amazon's referral fee is charged on the order total, but
    // this calculator takes the sale price and derives fulfilment from the
    // size tier instead of from what the buyer was charged for postage.
    // Folding postage into `salePrice` would inflate the referral fee and
    // print a worse number than the seller will actually see.
    fields: {
      price: 'salePrice',
      itemCost: 'costOfGoods',
      shippingCost: 'fbmShippingCost',
      packagingCost: 'packagingCost',
      otherCost: 'otherCost',
    },
  },
  {
    channel: 'mercari',
    slug: 'mercari-fee-calculator',
    label: 'Mercari fee calculator',
    // What it adds: the pre-January 6, 2025 legacy schedule compared
    // side-by-side with the current one, the note that buyer-paid shipping
    // sits inside the current fee base, and Mercari's separate Buyer
    // Protection Fee, which is a buyer-side charge this page does not model.
    //
    // Mercari has no separate packaging input -- its own `otherCost` field is
    // documented there as "packaging / prep cost" -- so packaging is folded
    // in rather than dropped, the same rule `combine` follows for every
    // other target with fewer inputs than this page.
    fields: {
      price: 'itemPrice',
      shippingCharged: 'buyerShipping',
      shippingCost: 'labelCost',
      itemCost: 'itemCost',
      otherCost: 'otherCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'reverb',
    slug: 'reverb-fee-calculator',
    label: 'Reverb fee & profit calculator',
    // What it adds: the decisions this page prices as one flat channel — an
    // offer to accept or counter, whether a bump pays for itself, Safe
    // Shipping against self-insuring a claim, consigning to a shop instead of
    // listing, eating the postage versus charging it, and what a return
    // actually costs once the fee refund is counted.
    //
    // The field names line up one-for-one, which is not luck: both tools were
    // written for the same shape of item. `packagingCost` is the one exception
    // — Reverb's calculator has no packaging input because gear packing (a
    // case, foam, a double box) is not a flat per-order cost there, so it
    // belongs in the general `otherCost` bucket rather than being dropped.
    fields: {
      price: 'price',
      shippingCharged: 'shippingCharged',
      shippingCost: 'shippingCost',
      itemCost: 'itemCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'own-store',
    slug: 'shopify-fee-calculator',
    label: 'Shopify fee & profit calculator',
    // What it adds: the question this page cannot ask, which is *which
    // processor*. An own store has no marketplace commission, so the whole
    // decision is Shopify Payments against PayPal or Stripe — and Shopify
    // charges an extra third-party transaction fee on top of the outside
    // processor's own rate, which generic fee pages leave out. Plus promos,
    // Shop Pay Installments, shipping labels, POS, refunds and chargebacks.
    //
    // `monthlyOrders` travels because the Shopify plan is a monthly fee, and
    // amortising it is the whole reason an own store can win on fees and lose
    // on cash. Arriving without it would price the plan against this page's
    // default order count rather than the seller's.
    fields: {
      price: 'price',
      shippingCharged: 'shippingCharged',
      shippingCost: 'shippingCost',
      itemCost: 'costOfGoods',
      packagingCost: 'packagingCost',
      otherCost: 'otherCost',
      monthlyOrders: 'monthlyOrders',
    },
  },
  {
    channel: 'tiktok',
    slug: 'tiktok-shop-fee-calculator',
    label: 'TikTok Shop fee calculator',
    // What it adds: the decisions this page prices as one flat referral rate —
    // organic versus affiliate-sourced orders, creator facilitation, the
    // announced 1 Oct 2026 fee-schedule change, free-shipping thresholds, and
    // bundle discounts.
    //
    // TikTok Shop has no separate "what you pay for shipping" field; its
    // `fulfillmentCost` covers pick/pack/label however the seller ships
    // (TikTok-fulfilled, 3PL, or their own postage), which is the natural home
    // for this page's `shippingCost`. It also has no separate packaging
    // input — `otherPerOrder` is documented there as "packaging, inserts,
    // payment-out fees" — so packaging is folded in rather than dropped, the
    // same rule `combine` follows for every other target with fewer inputs.
    fields: {
      price: 'itemPrice',
      shippingCharged: 'shippingCharged',
      shippingCost: 'fulfillmentCost',
      otherCost: 'otherPerOrder',
    },
    combine: { otherPerOrder: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'whatnot',
    slug: 'whatnot-seller-payout',
    label: 'Whatnot seller payout calculator',
    // What it adds: the category commission cap (TCG, coins, sports singles,
    // pallets), the giveaway shape, the per-show lot roll-up, and the price a
    // lot needs to clear a target leftover.
    //
    // Field names line up almost one-for-one — both tools were built for the
    // same shape of sale. Whatnot has no separate packaging input, so it is
    // folded into `otherCost`, which it does have, the same rule `combine`
    // follows for every other target with fewer inputs than this page.
    fields: {
      price: 'salePrice',
      shippingCharged: 'shippingCharged',
      shippingCost: 'shippingCost',
      itemCost: 'itemCost',
      otherCost: 'otherCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'poshmark',
    slug: 'poshmark-fee-calculator',
    label: 'Poshmark fee calculator',
    // What it adds: the two-tier schedule's effective rate on this exact
    // price, how much the flat $2.95 costs against what 20% would have
    // charged, the break-even price, and the offer-negotiation arithmetic —
    // whether accepting an offer that drops the price under $15 costs more
    // than the discount itself.
    //
    // Neither shipping field is mapped, and that is deliberate rather than an
    // omission: the buyer buys a prepaid label from Poshmark at checkout, so
    // it is neither seller revenue nor a seller cost, and the dedicated
    // calculator has no input for it at all. Mapping it anywhere would put
    // postage inside a payout that never sees it. This page's own Poshmark
    // preset starts both at zero for the same reason, so a comparison built
    // here has nothing to lose on the trip.
    fields: {
      price: 'salePrice',
      itemCost: 'itemCost',
      otherCost: 'otherCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'stockx',
    slug: 'stockx-seller-payout-calculator',
    label: 'StockX seller payout calculator',
    // What it adds: the two things this page prices as one flat rate and
    // cannot split — the seller-level fee band (two sellers moving the
    // identical pair at the identical price keep different amounts) and what
    // enrolling in Fast Shipping is worth against it — plus a month of flips
    // rolled up against a profit goal.
    //
    // `shippingCharged` is deliberately not mapped, and this is the one
    // channel where that is a fact about the marketplace rather than a
    // missing input: StockX is a bid/ask marketplace where the buyer pays
    // StockX for delivery, so no postage a buyer pays ever reaches the
    // seller. This page's own StockX preset pins the field to zero for the
    // same reason, so a comparison built here has nothing to lose on the
    // trip.
    fields: {
      price: 'salePrice',
      itemCost: 'itemCostBasis',
      shippingCost: 'shippingCost',
    },
    // Packaging is a real StockX cost (box, tape, a replacement lace bag) and
    // had nowhere to land until that calculator gained an `otherCost` bucket
    // alongside this handoff. Before it did, following this link would have
    // printed a *higher* profit than the comparison the seller had just read,
    // which is the silent-wrong-number failure this whole module exists to
    // prevent.
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'depop',
    slug: 'depop-fee-calculator',
    label: 'Depop fee calculator',
    // What it adds: the UK and rest-of-world schedules this page does not
    // price (the preset here is the US one), and Boosted Listings' extra 12%.
    // `region` is deliberately not sent: the receiving page defaults to the US
    // schedule, which is the one this page's preset prices, so the two agree.
    // Depop has no packaging input; packaging folds into `otherCost`.
    fields: {
      price: 'itemPrice',
      shippingCharged: 'buyerShipping',
      shippingCost: 'labelCost',
      itemCost: 'itemCost',
      otherCost: 'otherCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'grailed',
    slug: 'grailed-fee-calculator',
    label: 'Grailed fee calculator',
    // What it adds: the $1.99 minimum commission, international buyers, the
    // old flat 9% for comparison, and the $120 cliff worked out for the
    // shipping on screen. `schedule` is not sent: the receiving page
    // defaults to the domestic tiered schedule this page's row prices.
    // Packaging folds into `otherCost`.
    fields: {
      price: 'itemPrice',
      shippingCharged: 'buyerShipping',
      shippingCost: 'labelCost',
      itemCost: 'itemCost',
      otherCost: 'otherCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'facebook-marketplace',
    slug: 'facebook-marketplace-fee-calculator',
    label: 'Facebook Marketplace fee calculator',
    // What it adds: the $0.80 minimum fee (only bites under $8), the $20
    // dispute penalty, and the local-pickup case where the fee is zero.
    // `channel` is not sent: it defaults to shipped checkout, the case this
    // page's row prices. Packaging folds into `otherCost`.
    fields: {
      price: 'itemPrice',
      shippingCharged: 'buyerShipping',
      shippingCost: 'labelCost',
      itemCost: 'itemCost',
      otherCost: 'otherCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'tcgplayer',
    slug: 'tcgplayer-fee-calculator',
    label: 'TCGplayer fee calculator',
    // What it adds: order size (the $0.30 is per order, not per card), the
    // Pro seller schedule, the $75-per-product commission cap, and the sales
    // tax the processing fee is charged on. Packaging folds into
    // `otherCost`; `quantity` is left at its default of one card.
    fields: {
      price: 'itemPrice',
      shippingCharged: 'buyerShipping',
      shippingCost: 'shippingCost',
      itemCost: 'itemCost',
      otherCost: 'otherCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'discogs',
    slug: 'discogs-fee-calculator',
    label: 'Discogs fee calculator',
    // What it adds: the processing rate as an input, the $0.10 floor and $150
    // cap on the selling fee, the price that hits a target profit, and a fee
    // ladder from a $3 single to a $2,500 grail. Packaging folds into
    // `otherCost`, which that page documents as the packaging bucket.
    fields: {
      price: 'itemPrice',
      shippingCharged: 'buyerShipping',
      shippingCost: 'labelCost',
      itemCost: 'itemCost',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  },
  {
    channel: 'walmart',
    slug: 'walmart-marketplace-calculator',
    label: 'Walmart Marketplace calculator',
    // What it adds: WFS versus shipping it yourself (fulfilment by size tier,
    // storage, aged-inventory removal), Walmart Connect ads, returns, the
    // Buy Box price match, and two-day shipping.
    //
    // `shippingCharged` is deliberately not mapped: Walmart shows one price
    // with shipping included, and the dedicated calculator has no input for
    // buyer-paid postage. This page's Walmart preset starts it at zero for
    // the same reason, so nothing is lost on the trip. Our `shippingCost`
    // is what the seller pays to ship it themselves, which is exactly its
    // `sellerShippingCost`. The page opens on WFS by default; the
    // seller-fulfilled number it compares against is the one priced here.
    fields: {
      price: 'salePrice',
      shippingCost: 'sellerShippingCost',
      itemCost: 'costOfGoods',
      packagingCost: 'packagingCost',
      otherCost: 'otherCost',
    },
  },
];

const bySlugSafe = (value) => /^[a-z0-9-]+$/.test(value);

/** The handoff for a channel id, or null if it has no prefillable calculator. */
export function handoffFor(channel) {
  return HANDOFFS.find((entry) => entry.channel === channel) ?? null;
}

/**
 * The values to hand over, as `{targetField: number}`.
 *
 * Only finite, non-negative numbers travel. A blank or nonsense input is left
 * out entirely so the target falls back to its own default, rather than
 * arriving as `NaN` or a silent zero that reads as a real answer.
 */
export function handoffValues(entry, shared = {}) {
  const out = {};
  if (!entry) return out;

  const clean = (value) => {
    // `Number('')` and `Number(null)` are both 0, so coercing first would turn
    // an untouched field into an explicit zero and override the target's own
    // default — the silent-wrong-number case this whole module is guarding.
    if (value === null || value === undefined) return null;
    if (typeof value === 'string' && value.trim() === '') return null;
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : null;
  };

  for (const [source, target] of Object.entries(entry.fields)) {
    const value = clean(shared[source]);
    if (value !== null) out[target] = value;
  }

  // A target with fewer inputs than this page folds two of ours into one of
  // theirs, so the total cost survives the trip instead of being dropped.
  for (const [target, sources] of Object.entries(entry.combine ?? {})) {
    const parts = sources.map((source) => clean(shared[source])).filter((v) => v !== null);
    if (parts.length > 0) out[target] = parts.reduce((a, b) => a + b, 0);
  }

  return out;
}

/**
 * A relative link to the channel's calculator, carrying the item.
 *
 * Relative on purpose: the same href has to work under the project path prefix
 * GitHub Pages serves from, under a custom domain later, and from a local
 * `python3 -m http.server`. The values ride in the fragment, which browsers do
 * not send to any server.
 */
export function handoffUrl(channel, shared = {}) {
  const entry = handoffFor(channel);
  if (!entry || !bySlugSafe(entry.slug)) return null;

  const values = handoffValues(entry, shared);
  const params = new URLSearchParams();
  for (const field of Object.keys(values).sort()) params.set(field, String(values[field]));

  const query = params.toString();
  return `../${entry.slug}/${query ? `#${query}` : ''}`;
}

/**
 * Every available handoff for a comparison, best channel first.
 *
 * Ordered by the ranking the reader is looking at rather than by this table,
 * so the link they most likely want is the one they read first.
 */
export function handoffsForResults(results = [], shared = {}) {
  return results
    .slice()
    .sort((a, b) => (a.rank ?? 0) - (b.rank ?? 0))
    .map((result) => {
      const entry = handoffFor(result.id);
      if (!entry) return null;
      return {
        channel: result.id,
        label: entry.label,
        channelLabel: result.label ?? entry.channel,
        isBest: Boolean(result.isBest),
        href: handoffUrl(result.id, shared),
      };
    })
    .filter(Boolean);
}

/**
 * A relative link to `../marketplace-fee-compare/` carrying the item, for the
 * seller who wants the quick headline triage or the bulk catalogue view
 * instead of this page's returns-and-shelf-time depth.
 *
 * That page reads `#<encoded JSON>` with the item under `item` (its
 * `share.mjs`). Packaging has no field there, so it is folded into
 * `otherCost` rather than dropped, as for every other target. A blank item
 * gives the bare link, so the target shows its own defaults only when nothing
 * was entered.
 */
export function quickCompareUrl(shared = {}) {
  const entry = {
    fields: {
      price: 'price',
      shippingCharged: 'shippingCharged',
      shippingCost: 'shippingCost',
      itemCost: 'itemCost',
      monthlyOrders: 'monthlyOrders',
    },
    combine: { otherCost: ['otherCost', 'packagingCost'] },
  };
  const item = handoffValues(entry, shared);
  const base = '../marketplace-fee-compare/';
  if (Object.keys(item).length === 0) return base;
  return `${base}#${encodeURIComponent(JSON.stringify({ item }))}`;
}

