// Copies the web app (one directory up) into www/ for Capacitor. No bundler.
import { cpSync, rmSync, mkdirSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

export const KEEP = /\.(html|mjs|webmanifest|png|js)$/;
const src = fileURLToPath(new URL("..", import.meta.url));
const out = fileURLToPath(new URL("./www", import.meta.url));

export function webFiles(dir = src) {
  return readdirSync(dir, { withFileTypes: true })
    .filter((e) => (e.isFile() && KEEP.test(e.name) && !/\.test\.mjs$/.test(e.name) && !/^build-/.test(e.name))
      || (e.isDirectory() && e.name === "icons"))
    .map((e) => e.name);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  rmSync(out, { recursive: true, force: true });
  mkdirSync(out, { recursive: true });
  for (const f of webFiles()) cpSync(join(src, f), join(out, f), { recursive: true });
  console.log(`copied ${webFiles().length} entries to www/`);
}

share.mjs.text:
// Share only calculator assumptions in the URL. No saved inputs leave the
// browser except when the user explicitly copies a link.
//
// Every field the calculator reads must appear in one of these two lists. A
// field that is missing is silently dropped from the link, and the recipient
// then computes a different answer than the sender saw — the failure mode is
// a wrong number, not an error.
const SHARED_FIELDS = [
  "price", "shippingCharged", "shippingCost", "itemCost",
  "packagingCost", "otherCost", "monthlyOrders", "daysToSell",
  "horizonDays", "capitalCostPct", "unsoldRecoveryPct", "targetProfit",
];
const CHANNEL_FIELDS = [
  "price", "shippingCharged", "shippingCost", "fulfilmentCost",
  "commissionRate", "paymentRate", "paymentFixed", "perListingFee",
  "monthlyFee", "adRate", "expectedMonthlySales",
  "returnRate", "returnShippingCost", "resellableRate", "feeRefundRate",
  "sellThroughPct", "daysToSell", "listingRenewalDays",
];
// Not a number, so it rides alongside the numeric fields rather than in them.
const RANK_MODES = new Set(["profit", "profitPerDay"]);

function sharedNumber(value) {
  if (typeof value !== "number" && typeof value !== "string") return null;
  if (value === "") return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

export function encodeComparison(shared = {}, channels = []) {
  const payload = {
    shared: Object.fromEntries(SHARED_FIELDS
      .filter((key) => shared[key] !== undefined && shared[key] !== "")
      .map((key) => [key, shared[key]])),
    includeSubscription: shared.includeSubscription !== false,
    // Carried so a link opens on the same ranking the sender was reading. A
    // link that reorders the table under the recipient answers a different
    // question from the one that was shared.
    rankBy: RANK_MODES.has(shared.rankBy) ? shared.rankBy : "profit",
    includeReturns: shared.includeReturns !== false,
    channels: channels.map((channel) => ({
      id: channel.id,
      enabled: channel.enabled !== false,
      values: Object.fromEntries(CHANNEL_FIELDS
        .filter((key) => channel[key] !== undefined && channel[key] !== "")
        .map((key) => [key, channel[key]])),
    })),
  };
  return encodeURIComponent(JSON.stringify(payload));
}

export function decodeComparison(value) {
  try {
    const parsed = JSON.parse(decodeURIComponent(String(value || "")));
    if (!parsed || typeof parsed !== "object") return null;
    const shared = {};
    for (const key of SHARED_FIELDS) {
      const number = sharedNumber(parsed.shared?.[key]);
      if (number !== null) shared[key] = number;
    }
    const channels = Array.isArray(parsed.channels) ? parsed.channels
      .filter((channel) => channel && typeof channel.id === "string")
      .map((channel) => ({
        id: channel.id,
        enabled: channel.enabled !== false,
        // Coerce, do not merely pass through: a link is untrusted input, and a
        // non-numeric value used to survive this filter and reach the
        // calculator, where it surfaced as a validation error on a field the
        // recipient never typed. Dropping it falls back to the preset instead.
        ...Object.fromEntries(CHANNEL_FIELDS.map((key) => {
          const number = sharedNumber(channel.values?.[key]);
          return [key, number];
        }).filter(([, value]) => value !== null)),
      })) : [];
    const rankBy = RANK_MODES.has(parsed.rankBy) ? parsed.rankBy : "profit";
    return {
      shared,
      includeSubscription: parsed.includeSubscription !== false,
      rankBy,
      includeReturns: parsed.includeReturns !== false,
      channels,
    };
  } catch {
    return null;
  }
}

sourcing.mjs.text:
// The sourcing question: "I'm standing in a thrift store holding this. What is
// the most I can pay and still be happy with the best place to sell it?"
//
// The comparison on the main page takes what you paid as an input and reports
// profit. A reseller at the shelf has it the other way round: they know the
// likely sale price and need the ceiling on cost. Rather than re-derive each
// channel's fee algebra (and drift from calc.mjs the first time a fee rule
// changes), this inverts the real engine: it searches for the highest
// `itemCost` at which a channel still reaches the target, calling
// calculateChannel for every probe. Profit never rises as cost rises, so
// bisection is safe.
import { calculateChannel } from "./calc.mjs";

const CAP = 1_000_000;

/**
 * Highest item cost at which `channel` still keeps at least `target`, in the
 * same terms the main table ranks on (expected keep after returns unless
 * `shared.includeReturns === false`). Returns null when even a free item falls
 * short, so the caller can say "not worth it here at any price".
 */
export function maxBuyPriceForChannel(channel, shared = {}, target = 0) {
  const goal = Number(target);
  if (!Number.isFinite(goal)) throw new Error("Target profit must be a number");
  const useExpected = shared.includeReturns !== false;
  const keep = (itemCost) => {
    const r = calculateChannel(channel, { ...shared, itemCost });
    return useExpected ? r.expectedProfit : r.profit;
  };
  if (keep(0) < goal) return null;
  let hi = Math.max(1, Number(shared.price) || 1);
  while (keep(hi) >= goal) {
    hi *= 2;
    if (hi > CAP) return CAP;
  }
  let lo = 0;
  for (let i = 0; i < 60; i += 1) {
    const mid = (lo + hi) / 2;
    if (keep(mid) >= goal) lo = mid; else hi = mid;
  }
  return Math.floor(lo * 100) / 100;
}

/**
 * Per-channel ceilings for every switched-on channel, best first. `best` is the
 * channel that lets you pay the most, which is the one to plan the resale on.
 */
export function maxBuyPrices(channels, shared = {}, target = 0) {
  const active = channels.filter((c) => c?.enabled !== false);
  if (active.length === 0) throw new Error("Switch on at least one channel");
  const rows = active.map((channel) => ({
    id: channel.id,
    label: channel.label ?? channel.id,
    maxBuy: maxBuyPriceForChannel(channel, shared, target),
  }));
  rows.sort((a, b) => (b.maxBuy ?? -1) - (a.maxBuy ?? -1));
  return { target: Number(target), rows, best: rows[0].maxBuy === null ? null : rows[0] };
}

sw.js.text:
// Offline shell for the installed app. Caches this directory's own files only;
// there are no third-party requests and nothing is sent anywhere.
const CACHE = "where-to-sell-v1";
const SHELL = [
  "./", "./index.html", "./calc.mjs", "./export.mjs", "./handoff.mjs", "./sourcing.mjs", "./share.mjs", "./usage.mjs",
  "./does-it-actually-sell-there.html",
  "./etsy-vs-ebay-fees.html",
  "./returns-change-the-ranking.html",
  "./reverb-vs-ebay-for-gear.html",
  "./vs-crosslist.html",
  "./vs-each-marketplaces-own-calculator.html",
  "./vs-list-perfectly.html",
  "./vs-vendoo.html",
  "./manifest.webmanifest",
  "./icons/icon-192.png", "./icons/icon-512.png", "./icons/apple-touch-icon.png",
];
self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Network first so a fixed calculator reaches people at once; cache when offline.
self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith(
    fetch(req)
      .then((res) => {
        const copy = res.clone();
        if (res.ok) caches.open(CACHE).then((c) => c.put(req, copy));
        return res;
      })
      .catch(() => caches.match(req).then((hit) => hit || caches.match("./index.html"))),
  );
});

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores prices,
// costs, channel rates, or any other calculator input, and never leaves the
// device. There is no server to send it to.
const KEY = "where-to-sell-usage";

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === "1" || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = "comparison_calculated") {
  // The stored choice is consulted here as well as passed in. The page reads
  // it into the checkbox on load and hands the checkbox back, which works —
  // but it makes the promise depend on one line of page wiring, and a caller
  // that forgets the second argument would count a visitor who opted out.
  // The module now honours its own record of the choice either way.
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(KEY) || "{}");
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(KEY, JSON.stringify(current));
  } catch {
    // A full or unavailable storage quota must never break the calculator —
    // the counter is a convenience, the arithmetic is the product.
  }
}

export function readUsage(storage = globalThis.localStorage) {
  try {
    return JSON.parse(storage?.getItem(KEY) || "{}");
  } catch {
    return {};
  }
}

// The opt-out choice is itself kept locally so the visitor does not have to
// make it again on every visit.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${KEY}-opt-out`) === "1";
  } catch {
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  try {
    if (optedOut) {
      storage?.setItem(`${KEY}-opt-out`, "1");
      storage?.removeItem(KEY);
    } else {
      storage?.removeItem(`${KEY}-opt-out`);
    }
  } catch {
    // Ignore: see recordUsage.
  }
}
